// F-S1 lock: same-category cross-procomp via relative + specific-file path.
import { useEffect, useRef, useState } from "react";
import { VideoPlayer } from "../../video-player/video-player";
import type { VideoPlayerHandle } from "../../video-player/types";
import type {
  RenderItemContext,
  ResolvedStoryViewer01Labels,
  Story,
  StoryItem,
} from "../types";

export interface ItemViewProps {
  item: StoryItem;
  story: Story;
  totalItems: number;
  cursor: { storyIndex: number; itemIndex: number };
  isPaused: boolean;
  isMuted: boolean;
  /** Playable URL (`item.src`, a resolved URL or a retry URL). `undefined` while resolving: no media mounts. */
  src: string | undefined;
  /** Poster for a video item (from `resolveMedia`). */
  poster?: string;
  /** 0.7.0 - `srcset` / `sizes` for an image (item or resolved; absent after a retry). Video ignores them. */
  srcSet?: string;
  sizes?: string;
  /** 0.7.0 - the stage image loaded; `currentSrc` is the URL the browser actually picked. */
  onImageLoaded?: (currentSrc: string) => void;
  onLoadedMetadata: (duration: number) => void;
  onEnded: () => void;
  /** The item can start counting down: image loaded (or failed / was cached), video started (or failed). */
  onReady?: () => void;
  /** Video media time in seconds (`currentTime`, `duration`). */
  onTimeUpdate?: (currentTime: number, duration: number) => void;
  /** The video failed to load (every error event). The caller decides: timer fallback, retry or unavailable. */
  onVideoError?: () => void;
  /** The image failed to load (once per element). Without it a failed image counts as ready. */
  onImageError?: () => void;
  /** A custom `renderItem` frame called `ctx.onError`. */
  onFrameError?: () => void;
  /**
   * Passed to the video player's `onMediaError` (it asks once, swaps the URL and resumes at the same
   * time). When set, a failing video is not counted as ready: the retry is pending.
   */
  videoMediaError?: (failedSrc: string) => Promise<string | void>;
  /** Story-qualified key for the media element (stories may reuse item ids). Defaults to `item.id`. */
  mediaKey?: string;
  renderItem?: (item: StoryItem, context: RenderItemContext) => React.ReactNode;
  labels: ResolvedStoryViewer01Labels;
}

const noop = () => {};
const noopProgress: (currentTime: number, duration: number) => void = () => {};

export function ItemView({
  item,
  story,
  totalItems,
  cursor,
  isPaused,
  isMuted,
  src,
  poster,
  srcSet,
  sizes,
  onImageLoaded,
  onLoadedMetadata,
  onEnded,
  onReady,
  onTimeUpdate,
  onVideoError,
  onImageError,
  onFrameError,
  videoMediaError,
  mediaKey,
  renderItem,
  labels,
}: ItemViewProps) {
  const elementKey = mediaKey ?? item.id;
  // An element is reported broken once.
  const reportedBroken = useRef(new WeakSet<HTMLImageElement>());
  // Elements that fired `error`, and elements already reported ready through the `complete` check.
  // A failed `<img>` also has `complete === true`, and React 19 re-runs an inline ref on every
  // render, so neither a failure nor a repeat render may mark an element ready.
  const failedImages = useRef(new WeakSet<HTMLImageElement>());
  const readyImages = useRef(new WeakSet<HTMLImageElement>());
  // 0.7.0 - the src whose image failed: it is hidden at once (no broken-image glyph) until a new
  // src replaces it.
  const [brokenSrc, setBrokenSrc] = useState<string | null>(null);
  // 0.7.0 - `isActive={false}` pauses the player but nothing restarted it: a video paused (Space,
  // a sheet, a hold, a paused move onto it) stayed frozen after the viewer resumed. Play it on every
  // paused -> playing change; a refusal (autoplay policy) is swallowed by the player.
  const videoRef = useRef<VideoPlayerHandle>(null);
  const wasPausedRef = useRef(isPaused);
  useEffect(() => {
    const was = wasPausedRef.current;
    wasPausedRef.current = isPaused;
    if (was && !isPaused) void videoRef.current?.play();
  }, [isPaused]);
  if (renderItem) {
    return (
      <div className="absolute inset-0 flex items-center justify-center">
        {renderItem(item, {
          storyIndex: cursor.storyIndex,
          itemIndex: cursor.itemIndex,
          isPaused,
          isMuted,
          src,
          poster,
          srcSet,
          sizes,
          onReady: onReady ?? noop,
          onEnded,
          onProgress: onTimeUpdate ?? noopProgress,
          onError: onFrameError ?? noop,
        })}
      </div>
    );
  }

  // Resolving (no URL yet): nothing to mount, the item is not ready.
  if (src === undefined) return null;

  if (item.type === "image") {
    return (
      <div className="absolute inset-0 flex items-center justify-center">
        <img
          key={`${elementKey}|${src}`}
          ref={(el) => {
            // Cached / already-decoded image: `load` fired before we attached. Once per element,
            // and never for a failed one (a failed image is `complete` with no intrinsic size).
            if (!el || !el.complete || readyImages.current.has(el)) return;
            if (el.naturalWidth === 0 && failedImages.current.has(el)) return;
            readyImages.current.add(el);
            onImageLoaded?.(el.currentSrc || el.src);
            onReady?.();
          }}
          src={src}
          srcSet={srcSet}
          sizes={sizes}
          alt={labels.itemImageAlt(story, cursor.itemIndex, totalItems)}
          className="h-full w-full object-cover"
          style={brokenSrc === src ? { visibility: "hidden" } : undefined}
          onLoad={(e) => {
            onImageLoaded?.(e.currentTarget.currentSrc || e.currentTarget.src);
            onReady?.();
          }}
          // A failed image counts as ready — the story must never freeze on it —
          // unless the caller takes the failure over (retry / unavailable).
          onError={(e) => {
            failedImages.current.add(e.currentTarget);
            setBrokenSrc(src);
            if (!onImageError) {
              onReady?.();
              return;
            }
            if (reportedBroken.current.has(e.currentTarget)) return;
            reportedBroken.current.add(e.currentTarget);
            onImageError();
          }}
        />
      </div>
    );
  }

  return (
    <div className="absolute inset-0">
      <VideoPlayer
        ref={videoRef}
        key={elementKey}
        src={src}
        poster={poster}
        isActive={!isPaused}
        muted={isMuted}
        loop={false}
        autoPlay
        controls={false}
        objectFit="cover"
        className="h-full w-full"
        videoClassName="h-full w-full"
        onLoadedMetadata={onLoadedMetadata}
        onEnded={onEnded}
        onPlay={onReady}
        onTimeUpdate={(currentTime, duration) => {
          if (currentTime > 0) onReady?.();
          onTimeUpdate?.(currentTime, duration);
        }}
        onMediaError={videoMediaError}
        onError={() => {
          // With a media-error handler the retry is pending: not ready yet.
          if (!videoMediaError) onReady?.();
          onVideoError?.();
        }}
      />
    </div>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useMemo,
  useReducer,
  useRef,
  useState,
} from "react";
import type {
  Story,
  StoryItem,
  StoryItemUnavailableReason,
  StoryItemViewedCause,
  StoryItemViewedInfo,
  StoryViewerDelta,
  StoryViewerLocalAction,
  StoryViewerPendingRemoval,
  Subscribe,
} from "../types";

// ─── Pure helpers ────────────────────────────────────────────────────────────

function insertStoryAtPosition(
  state: Story[],
  story: Story,
  position: "start" | "end" | undefined,
): Story[] {
  if (position === "start") return [story, ...state];
  return [...state, story]; // default "end" — cursor-stable for ID-anchored cursor
}

function removeStoryById(state: Story[], id: string): Story[] {
  const next = state.filter((s) => s.id !== id);
  return next.length === state.length ? state : next;
}

function patchStoryById(
  state: Story[],
  id: string,
  patch: Partial<Story>,
): Story[] {
  let mutated = false;
  const next = state.map((s) => {
    if (s.id !== id) return s;
    mutated = true;
    return { ...s, ...patch };
  });
  return mutated ? next : state;
}

function addItemToStory(
  state: Story[],
  storyId: string,
  item: StoryItem,
  position: "start" | "end" | undefined,
): Story[] {
  let mutated = false;
  const next = state.map((s) => {
    if (s.id !== storyId) return s;
    mutated = true;
    const items = position === "start" ? [item, ...s.items] : [...s.items, item];
    return { ...s, items };
  });
  return mutated ? next : state;
}

function removeItemFromStory(
  state: Story[],
  storyId: string,
  itemId: string,
): Story[] {
  let mutated = false;
  const next = state.map((s) => {
    if (s.id !== storyId) return s;
    const items = s.items.filter((i) => i.id !== itemId);
    if (items.length === s.items.length) return s;
    mutated = true;
    return { ...s, items };
  });
  return mutated ? next : state;
}

// ─── Reducer ─────────────────────────────────────────────────────────────────

/** Pure reducer — exported for hosts driving their own state. */
export function storyViewerReducer(
  state: Story[],
  action: StoryViewerLocalAction,
): Story[] {
  switch (action.kind) {
    case "add-story":
      return insertStoryAtPosition(state, action.story, action.position);
    case "remove-story":
      return removeStoryById(state, action.storyId);
    case "add-item":
      return addItemToStory(state, action.storyId, action.item, action.position);
    case "remove-item":
      return removeItemFromStory(state, action.storyId, action.itemId);
    case "patch-story":
      return patchStoryById(state, action.storyId, action.partial);
    case "subscribe-delta": {
      const d = action.delta;
      switch (d.kind) {
        case "story-added":
          return insertStoryAtPosition(state, d.story, d.position);
        case "story-removed":
          return removeStoryById(state, d.storyId);
        case "item-added":
          return addItemToStory(state, d.storyId, d.item, d.position);
        case "item-removed":
          return removeItemFromStory(state, d.storyId, d.itemId);
        case "story-viewed":
          return patchStoryById(state, d.storyId, { hasUnread: false });
      }
      return state;
    }
    case "reset":
      return action.next;
  }
}

// ─── Internal cursor (ID-anchored) ──────────────────────────────────────────

interface CursorIds {
  storyId: string;
  itemId: string;
}

/** Last known valid cursor position — lets removal resolve "the next one". */
interface LastPosition {
  storyId: string;
  storyIndex: number;
  itemIndex: number;
}

/** Last on-screen story/item snapshot — the frame a removal notice keeps. */
interface LastValid {
  storyId: string;
  itemId: string;
  story: Story;
  item: StoryItem;
}

/**
 * Resolve a cursor that may name a removed (or never-seen) story/item.
 *
 * Returns the cursor unchanged when it is valid. Otherwise picks, in order:
 * the next item of the same group, the first item of the next group, then
 * (nothing after) the nearest earlier item. Returns `null` when no item exists
 * anywhere (empty list / every group empty).
 */
function resolveCursor(
  stories: Story[],
  ids: CursorIds,
  last: LastPosition,
): CursorIds | null {
  const sIdx = stories.findIndex((s) => s.id === ids.storyId);
  // A repair is a sequential move, so it skips groups the host muted (the same
  // rule as `findAdjacentStoryIndex`). Not before the first real cursor (`""`):
  // that is the first data arrival, which may legitimately land on a muted group.
  const skipMuted = ids.storyId !== "";
  const firstOf = (from: number): CursorIds | null => {
    for (let k = Math.max(0, from); k < stories.length; k++) {
      if (skipMuted && stories[k].muted) continue;
      const first = stories[k].items[0];
      if (first) return { storyId: stories[k].id, itemId: first.id };
    }
    return null;
  };
  const lastBefore = (from: number): CursorIds | null => {
    for (let k = Math.min(from, stories.length - 1); k >= 0; k--) {
      if (skipMuted && stories[k].muted) continue;
      const items = stories[k].items;
      const tail = items[items.length - 1];
      if (tail) return { storyId: stories[k].id, itemId: tail.id };
    }
    return null;
  };
  if (sIdx >= 0) {
    const story = stories[sIdx];
    if (story.items.some((i) => i.id === ids.itemId)) return ids;
    // Item gone (removed, or group opened empty and just received items).
    const at = last.storyId === ids.storyId ? last.itemIndex : 0;
    const next = story.items[at];
    if (next) return { storyId: story.id, itemId: next.id };
    return firstOf(sIdx + 1) ?? lastBefore(sIdx);
  }
  // Group gone (removed, reset away, or never existed): the group that now sits
  // at its old index is "the next group".
  return firstOf(last.storyIndex) ?? lastBefore(last.storyIndex - 1);
}

/**
 * Index of the nearest group from `from` in `dir` (1 forward, -1 backward) that
 * the host has not muted, or -1. Every sequential move uses this; direct opens
 * (`initialStoryIndex`, `goToStoryIndex`) do not.
 */
export function findAdjacentStoryIndex(
  stories: Story[],
  from: number,
  dir: 1 | -1,
): number {
  for (let k = from + dir; k >= 0 && k < stories.length; k += dir) {
    if (!stories[k].muted) return k;
  }
  return -1;
}

// ─── Hook ────────────────────────────────────────────────────────────────────

export interface UseStoryViewerStateOptions {
  /**
   * Uncontrolled: captured ON MOUNT only — subsequent changes are ignored.
   * Controlled (`onStoriesChange` passed): the live list, read on every render.
   */
  initialStories: Story[];
  /** Re-seeds cursor whenever (initialStoryIndex, isOpen) pair changes. */
  initialStoryIndex: number;
  /** 0.7.0 - item of the opening story to start on (clamped; default 0). Read with `initialStoryIndex`. */
  initialItemIndex?: number;
  /** Re-seeds cursor whenever (initialStoryIndex, isOpen) pair changes. */
  isOpen: boolean;

  subscribe?: Subscribe<StoryViewerDelta>;
  onSubscribeDelta?: (delta: StoryViewerDelta) => void;

  onStoryViewed?: (storyId: string) => void;
  onItemViewed?: (
    storyId: string,
    itemId: string,
    itemIndex: number,
    cause: StoryItemViewedCause,
    info: StoryItemViewedInfo,
  ) => void;
  onCursorChange?: (storyIndex: number, itemIndex: number) => void;
  onAutoCloseAtEnd?: (storyId: string, itemId: string) => void;
  onClose: () => void;
  /**
   * v0.2.0 — when true, the auto-close at end of the last story fires
   * `onAutoCloseAtEnd` but DOES NOT call `onClose()`. The viewer stays
   * open at the last item. Default false. Mirrors the `disableAutoClose`
   * opt-out on StoryViewerProps.
   */
  disableAutoClose?: boolean;
  /**
   * 0.6.0 — controlled `stories`: when passed, `initialStories` wins on every
   * render and local mutations are reported here instead of being applied.
   */
  onStoriesChange?: (next: Story[], change: StoryViewerLocalAction) => void;
  /** 0.6.0 — fires once (`"removed"`) when the on-screen item leaves `stories`. */
  onItemUnavailable?: (
    storyId: string,
    itemId: string,
    reason: StoryItemUnavailableReason,
  ) => void;
  /** 0.6.0 — removal notice duration in ms (default 1500; 0 = repair at once). */
  unavailableNoticeMs?: number;
  /** 0.6.0 — opened from a link: a single-item story's notice stays until close. */
  standalone?: boolean;
  /** 0.6.0 — controlled pause reasons (wins every render when defined). */
  pauseReasons?: string[];
  /** 0.6.0 — reports every reason change. */
  onPauseReasonsChange?: (next: string[]) => void;
}

export interface UseStoryViewerStateResult {
  stories: Story[];
  /** Public derived cursor (indices for caller; IDs are internal). */
  cursor: { storyIndex: number; itemIndex: number };
  /** True while any pause reason is active (or a removal notice is held). */
  isPaused: boolean;
  isMuted: boolean;
  /**
   * `true` adds the `host` reason, `false` removes `host` + `user`. The
   * functional form (`p => !p`) is the user toggle: it adds / removes `user`.
   */
  setPaused: React.Dispatch<React.SetStateAction<boolean>>;
  setMuted: React.Dispatch<React.SetStateAction<boolean>>;
  goToPrevItem: () => void;
  /**
   * Advance one item. `cause` is what `onItemViewed` reports for the item left:
   * `"completed"` only when it played to the end (progress completion / video
   * ended); anything else (taps, keys, screen-reader next, handle) is `"left"`,
   * which is the default. Any non-`"completed"` argument (e.g. a click event
   * passed straight through as a handler) is treated as `"left"`.
   */
  goToNextItem: (cause?: StoryItemViewedCause) => void;
  goToPrevStory: () => void;
  goToNextStory: () => void;
  goToStoryIndex: (index: number) => void;
  goToItemIndex: (index: number) => void;
  reset: (next: Story[]) => void;
  dispatch: React.Dispatch<StoryViewerLocalAction>;
  /**
   * Bumps each time the cursor was repaired because its story/item vanished
   * (removal / reset / first data arrival). Lets the shell skip the cube
   * animation for that snap.
   */
  snapCount: number;
  /** 0.6.0 — the active pause reasons (controlled list, or the internal one). */
  pauseReasons: string[];
  /** 0.6.0 — add a pause reason (no-op when present). Identity-stable. */
  addPauseReason: (reason: string) => void;
  /** 0.6.0 — remove pause reasons (no-op when absent). Identity-stable. */
  removePauseReason: (...reasons: string[]) => void;
  /** 0.6.0 — set while the removed on-screen item's notice frame is held. */
  pendingRemoval: StoryViewerPendingRemoval | null;
}

export function useStoryViewerState(
  opts: UseStoryViewerStateOptions,
): UseStoryViewerStateResult {
  const {
    initialStories,
    initialStoryIndex,
    initialItemIndex = 0,
    isOpen,
    subscribe,
    onSubscribeDelta,
    onStoryViewed,
    onItemViewed,
    onCursorChange,
    onAutoCloseAtEnd,
    onClose,
    disableAutoClose = false,
    onStoriesChange,
    onItemUnavailable,
    unavailableNoticeMs = 1500,
    standalone = false,
    pauseReasons: pauseReasonsProp,
    onPauseReasonsChange,
  } = opts;
  const disableAutoCloseRef = useRef(disableAutoClose);
  useEffect(() => {
    disableAutoCloseRef.current = disableAutoClose;
  });

  // ─── Stories: uncontrolled reducer, or the controlled prop ──────────────
  const storiesControlled = onStoriesChange !== undefined;
  const [localStories, localDispatch] = useReducer(
    storyViewerReducer,
    initialStories,
  );
  const stories = storiesControlled ? initialStories : localStories;

  const initialStoriesRef = useRef(stories);
  useEffect(() => {
    initialStoriesRef.current = stories;
  });

  // Refs-mirror for callbacks so effect deps stay narrow.
  const onSubscribeDeltaRef = useRef(onSubscribeDelta);
  const onStoryViewedRef = useRef(onStoryViewed);
  const onItemViewedRef = useRef(onItemViewed);
  const onCursorChangeRef = useRef(onCursorChange);
  const onAutoCloseAtEndRef = useRef(onAutoCloseAtEnd);
  const onCloseRef = useRef(onClose);
  const onStoriesChangeRef = useRef(onStoriesChange);
  const onItemUnavailableRef = useRef(onItemUnavailable);
  const onPauseReasonsChangeRef = useRef(onPauseReasonsChange);
  useEffect(() => {
    onSubscribeDeltaRef.current = onSubscribeDelta;
    onStoryViewedRef.current = onStoryViewed;
    onItemViewedRef.current = onItemViewed;
    onCursorChangeRef.current = onCursorChange;
    onAutoCloseAtEndRef.current = onAutoCloseAtEnd;
    onCloseRef.current = onClose;
    onStoriesChangeRef.current = onStoriesChange;
    onItemUnavailableRef.current = onItemUnavailable;
    onPauseReasonsChangeRef.current = onPauseReasonsChange;
  });

  // Latest list the controlled prop holds. A mutation computes from it, reports
  // `next`, and keeps `next` as the base for further mutations in the same task
  // (several dispatches before the host re-renders); a microtask drops back to
  // the prop so a change the host rejects can't leak into later ones.
  const propStoriesRef = useRef(stories);
  const storiesBaseRef = useRef(stories);
  useLayoutEffect(() => {
    propStoriesRef.current = stories;
    storiesBaseRef.current = stories;
  });
  const dispatch = useCallback((action: StoryViewerLocalAction) => {
    const report = onStoriesChangeRef.current;
    if (!report) {
      localDispatch(action);
      return;
    }
    const base = storiesBaseRef.current;
    const next = storyViewerReducer(base, action);
    if (next === base) return;
    storiesBaseRef.current = next;
    queueMicrotask(() => {
      storiesBaseRef.current = propStoriesRef.current;
    });
    report(next, action);
  }, []);

  // Subscribe wiring (mount-scoped; identity-stable per host convention).
  useEffect(() => {
    if (!subscribe) return;
    const unsub = subscribe((delta) => {
      onSubscribeDeltaRef.current?.(delta);
      dispatch({ kind: "subscribe-delta", delta });
    });
    return unsub;
  }, [subscribe, dispatch]);

  // ─── Pause reasons ────────────────────────────────────────────────────────
  const reasonsControlled = pauseReasonsProp !== undefined;
  const reasonsControlledRef = useRef(reasonsControlled);
  const [localReasons, setLocalReasons] = useState<string[]>([]);
  const reasons = reasonsControlled ? pauseReasonsProp : localReasons;
  const propReasonsRef = useRef(reasons);
  const reasonsBaseRef = useRef(reasons);
  useLayoutEffect(() => {
    reasonsControlledRef.current = reasonsControlled;
    propReasonsRef.current = reasons;
    reasonsBaseRef.current = reasons;
  });
  const commitReasons = useCallback((next: string[]) => {
    reasonsBaseRef.current = next;
    if (reasonsControlledRef.current) {
      queueMicrotask(() => {
        reasonsBaseRef.current = propReasonsRef.current;
      });
    } else {
      setLocalReasons(next);
    }
    onPauseReasonsChangeRef.current?.(next);
  }, []);
  const addPauseReason = useCallback(
    (reason: string) => {
      const cur = reasonsBaseRef.current;
      if (cur.includes(reason)) return;
      commitReasons([...cur, reason]);
    },
    [commitReasons],
  );
  const removePauseReason = useCallback(
    (...drop: string[]) => {
      const cur = reasonsBaseRef.current;
      const next = cur.filter((r) => !drop.includes(r));
      if (next.length === cur.length) return;
      commitReasons(next);
    },
    [commitReasons],
  );

  // ─── Cursor state (ID-anchored) ───────────────────────────────────────────
  // Lazy initializer — runs once at mount, derived from props.
  const seedCursor = (list: Story[]): CursorIds | null => {
    const idx = Math.max(0, Math.min(initialStoryIndex, list.length - 1));
    const story = list[idx];
    if (!story) return null;
    const iIdx = Math.max(0, Math.min(Math.trunc(initialItemIndex) || 0, story.items.length - 1));
    return { storyId: story.id, itemId: story.items[iIdx]?.id ?? "" };
  };
  const [cursorIdsState, setCursorIds] = useState<CursorIds>(
    () => seedCursor(initialStories) ?? { storyId: "", itemId: "" },
  );
  // 0.7.0 (A1) - re-seed the cursor when the viewer opens or `initialStoryIndex` changes, DURING
  // render: the render with the stale cursor is discarded (it never commits), so no other item is
  // rendered or handed to `resolveMedia` first - also on a reopen. A seed needs a story: opened on an
  // empty list, the seed waits (the key stays unmatched) and lands with the first data.
  const seedKey = isOpen ? `${initialStoryIndex}` : "";
  const [prevSeedKey, setPrevSeedKey] = useState(() =>
    seedCursor(initialStories) ? seedKey : "",
  );
  let cursorIds = cursorIdsState;
  if (prevSeedKey !== seedKey) {
    const seeded = isOpen ? seedCursor(stories) : null;
    if (seeded || !isOpen) setPrevSeedKey(seedKey);
    if (seeded) {
      setCursorIds(seeded);
      cursorIds = seeded;
    }
  }

  // Repair a cursor that names a removed id (render-time setState — the
  // discarded pass never commits, so there is no flash of the stale cursor).
  const [lastPos, setLastPos] = useState<LastPosition>({
    storyId: cursorIds.storyId,
    storyIndex: 0,
    itemIndex: 0,
  });
  const [lastValid, setLastValid] = useState<LastValid | null>(() => {
    const story = initialStories.find((s) => s.id === cursorIds.storyId);
    const item = story?.items.find((i) => i.id === cursorIds.itemId);
    return story && item
      ? { storyId: story.id, itemId: item.id, story, item }
      : null;
  });
  const [snapCount, setSnapCount] = useState(0);
  const resolved = resolveCursor(stories, cursorIds, lastPos);
  const cursorInvalid =
    resolved === null
      ? cursorIds.storyId !== ""
      : resolved.storyId !== cursorIds.storyId ||
        resolved.itemId !== cursorIds.itemId;

  // ─── Removal notice ───────────────────────────────────────────────────────
  // The on-screen item vanished (controlled prop, dispatch, reset, subscribe):
  // hold a notice frame for `unavailableNoticeMs`, then repair. `0` repairs now.
  const removalCandidate =
    cursorInvalid &&
    isOpen &&
    !!lastValid &&
    lastValid.storyId === cursorIds.storyId &&
    lastValid.itemId === cursorIds.itemId;
  const removalKey = `${cursorIds.storyId}:${cursorIds.itemId}`;
  const stayUntilClosed = standalone && lastValid?.story.items.length === 1;
  const [releasedKey, setReleasedKey] = useState("");
  const holding =
    removalCandidate && unavailableNoticeMs > 0 && releasedKey !== removalKey;
  // One event per removal, recorded at first sight and fired from an effect
  // (render may be discarded). `episode` guards against recording twice.
  const [removalEvent, setRemovalEvent] = useState<CursorIds | null>(null);
  const [episode, setEpisode] = useState(false);
  // The host reacted to `onItemUnavailable(…, "resolve" | "media" | "timeout")` by removing
  // that very item: its notice is already on screen (the media pipeline holds the
  // `unavailable` reason). The removal is then the same notice, not a second one.
  const [alreadyNoticed, setAlreadyNoticed] = useState(false);
  if (removalCandidate && !episode) {
    setEpisode(true);
    if (reasons.includes("unavailable")) setAlreadyNoticed(true);
    else setRemovalEvent({ storyId: cursorIds.storyId, itemId: cursorIds.itemId });
  } else if (!cursorInvalid && episode) {
    setEpisode(false);
    setAlreadyNoticed(false);
  }
  if (!cursorInvalid && releasedKey !== "") setReleasedKey("");
  useEffect(() => {
    if (!removalEvent) return;
    onItemUnavailableRef.current?.(
      removalEvent.storyId,
      removalEvent.itemId,
      "removed",
    );
  }, [removalEvent]);
  // When the media notice was already showing, only what is left of it is held. 0.7.0 (A8): the
  // time it already ran counts only while no OTHER pause reason held (`elapsed` + the running
  // segment `since`), so a pause before the hand-over never shortens the removal notice.
  const noticeClockRef = useRef<{ since: number | null; elapsed: number }>({ since: null, elapsed: 0 });
  // 0.6.2 - the notice counts down only while no OTHER pause reason holds (the notice's own
  // reason is `unavailable`); the remaining time carries across the pause.
  const otherHolds = reasons.some((r) => r !== "unavailable");
  const removalLeftRef = useRef<{ key: string; ms: number } | null>(null);
  useEffect(() => {
    if (!holding || stayUntilClosed) {
      removalLeftRef.current = null;
      return;
    }
    if (removalLeftRef.current?.key !== removalKey) {
      let ms = unavailableNoticeMs;
      if (alreadyNoticed) {
        const clock = noticeClockRef.current;
        const used = clock.elapsed + (clock.since === null ? 0 : Date.now() - clock.since);
        ms = Math.max(0, ms - used);
      }
      removalLeftRef.current = { key: removalKey, ms };
    }
    if (otherHolds) return;
    const left = removalLeftRef.current;
    const startedAt = Date.now();
    const t = window.setTimeout(() => setReleasedKey(removalKey), left.ms);
    return () => {
      window.clearTimeout(t);
      left.ms = Math.max(0, left.ms - (Date.now() - startedAt));
    };
  }, [holding, stayUntilClosed, removalKey, unavailableNoticeMs, alreadyNoticed, otherHolds]);

  if (!holding && cursorInvalid && resolved) {
    setCursorIds(resolved);
    setSnapCount((c) => c + 1);
  }
  const ids = holding ? cursorIds : (resolved ?? cursorIds);

  // Remember the last valid on-screen story/item (identity-compared so it
  // converges): the notice frame is built from it once the item is gone.
  if (!cursorInvalid && resolved) {
    const story = stories.find((s) => s.id === resolved.storyId);
    const item = story?.items.find((i) => i.id === resolved.itemId);
    if (
      story &&
      item &&
      (lastValid?.story !== story || lastValid?.item !== item)
    ) {
      setLastValid({ storyId: story.id, itemId: item.id, story, item });
    }
  }

  // Derive indices from IDs.
  const cursor = useMemo(() => {
    if (holding) {
      return { storyIndex: lastPos.storyIndex, itemIndex: lastPos.itemIndex };
    }
    const storyIndex = Math.max(0, stories.findIndex((s) => s.id === ids.storyId));
    const story = stories[storyIndex];
    const itemIndex = story
      ? Math.max(0, story.items.findIndex((i) => i.id === ids.itemId))
      : 0;
    return { storyIndex, itemIndex };
  }, [stories, ids.storyId, ids.itemId, holding, lastPos.storyIndex, lastPos.itemIndex]);

  if (
    !holding &&
    resolved &&
    (lastPos.storyId !== resolved.storyId ||
      lastPos.storyIndex !== cursor.storyIndex ||
      lastPos.itemIndex !== cursor.itemIndex)
  ) {
    setLastPos({
      storyId: resolved.storyId,
      storyIndex: cursor.storyIndex,
      itemIndex: cursor.itemIndex,
    });
  }

  const pendingRemoval = useMemo<StoryViewerPendingRemoval | null>(
    () =>
      holding && lastValid
        ? {
            storyId: cursorIds.storyId,
            itemId: cursorIds.itemId,
            reason: "removed",
            story: lastValid.story,
            item: lastValid.item,
            stayUntilClosed,
          }
        : null,
    [holding, lastValid, cursorIds.storyId, cursorIds.itemId, stayUntilClosed],
  );
  const hasPendingRemoval = pendingRemoval !== null;
  useLayoutEffect(() => {
    if (hasPendingRemoval) return;
    const clock = noticeClockRef.current;
    if (!reasons.includes("unavailable")) {
      clock.since = null;
      clock.elapsed = 0;
      return;
    }
    if (otherHolds) {
      if (clock.since !== null) {
        clock.elapsed += Date.now() - clock.since;
        clock.since = null;
      }
    } else if (clock.since === null) {
      clock.since = Date.now();
    }
  });
  useLayoutEffect(() => {
    if (hasPendingRemoval) addPauseReason("unavailable");
    else removePauseReason("unavailable");
  }, [hasPendingRemoval, addPauseReason, removePauseReason]);

  // Every group/item was removed while the viewer is open — nothing left to
  // show, so close (once per transition into the empty state), after the notice.
  const removedAll = resolved === null && cursorIds.storyId !== "" && !holding;
  useEffect(() => {
    if (removedAll && isOpen) onCloseRef.current();
  }, [removedAll, isOpen]);

  // Fire onCursorChange whenever derived indices change.
  const lastCursorRef = useRef(cursor);
  useEffect(() => {
    const last = lastCursorRef.current;
    if (last.storyIndex !== cursor.storyIndex || last.itemIndex !== cursor.itemIndex) {
      lastCursorRef.current = cursor;
      onCursorChangeRef.current?.(cursor.storyIndex, cursor.itemIndex);
    }
  }, [cursor]);

  // ─── Pause / mute ────────────────────────────────────────────────────────
  const [isMuted, setMuted] = useState(true);
  const isPaused = reasons.length > 0 || hasPendingRemoval;
  const isPausedRef = useRef(isPaused);
  useLayoutEffect(() => {
    isPausedRef.current = isPaused;
  });
  const setPaused = useCallback<React.Dispatch<React.SetStateAction<boolean>>>(
    (value) => {
      const functional = typeof value === "function";
      const next = functional ? value(isPausedRef.current) : value;
      if (next) addPauseReason(functional ? "user" : "host");
      else removePauseReason("host", "user");
    },
    [addPauseReason, removePauseReason],
  );

  // `user` (middle tap / Space) is per item: it clears on item change and when
  // the viewer closes. `host` survives item changes but not a close (a reopen must not
  // start silently paused); a `setPaused(true)` made while closed still holds,
  // because it clears on the close TRANSITION, not on open. `hold` can't outlive a closed viewer.
  const itemKey = `${ids.storyId}:${ids.itemId}`;
  const prevItemKeyRef = useRef(itemKey);
  useLayoutEffect(() => {
    if (prevItemKeyRef.current === itemKey) return;
    prevItemKeyRef.current = itemKey;
    removePauseReason("user");
  }, [itemKey, removePauseReason]);
  useLayoutEffect(() => {
    if (!isOpen) removePauseReason("user", "hold", "host");
  }, [isOpen, removePauseReason]);

  // A backgrounded tab pauses; coming back resumes (unless something else holds).
  useEffect(() => {
    if (!isOpen || typeof document === "undefined") return;
    const sync = () => {
      if (document.visibilityState === "hidden") addPauseReason("hidden-tab");
      else removePauseReason("hidden-tab");
    };
    sync();
    document.addEventListener("visibilitychange", sync);
    return () => {
      document.removeEventListener("visibilitychange", sync);
      removePauseReason("hidden-tab");
    };
  }, [isOpen, addPauseReason, removePauseReason]);

  // ─── onItemViewed: once per item visit, with a direction (0.7.0, A2) ─────────
  // A visit starts when the item becomes current (or the viewer opens) and ends when the cursor
  // leaves it. `viewedKeyRef` holds the item already reported in this visit, so the several paths
  // that can end it (a play-through, then the auto-close, then `isOpen` -> false) report it once.
  const viewedKeyRef = useRef("");
  const visitKey = `${cursorIds.storyId}:${cursorIds.itemId}`;
  useLayoutEffect(() => {
    if (isOpen) viewedKeyRef.current = "";
  }, [isOpen, visitKey]);
  const fireViewed = useCallback(
    (
      story: Story,
      iIdx: number,
      cause: StoryItemViewedCause,
      direction: StoryItemViewedInfo["direction"],
    ) => {
      const item = story.items[iIdx];
      if (!item) return;
      const key = `${story.id}:${item.id}`;
      if (viewedKeyRef.current === key) return;
      viewedKeyRef.current = key;
      onItemViewedRef.current?.(story.id, item.id, iIdx, cause, { direction });
    },
    [],
  );
  // Closing the viewer on an item (close button, Escape, backdrop, `isOpen` false) leaves it.
  const prevOpenRef = useRef(isOpen);
  useLayoutEffect(() => {
    const wasOpen = prevOpenRef.current;
    prevOpenRef.current = isOpen;
    if (!wasOpen || isOpen) return;
    const story = initialStoriesRef.current.find((s) => s.id === cursorIds.storyId);
    if (!story) return;
    fireViewed(
      story,
      story.items.findIndex((i) => i.id === cursorIds.itemId),
      "left",
      "close",
    );
  }, [isOpen, cursorIds, fireViewed]);

  // ─── Navigation helpers ──────────────────────────────────────────────────
  // While a removal notice is held, any navigation just ends the notice early
  // (it repairs to the next item) — unless it must stay until the viewer closes.
  const releaseNotice = useCallback(() => {
    if (stayUntilClosed) return;
    setReleasedKey(removalKey);
  }, [stayUntilClosed, removalKey]);

  const goToPrevItem = useCallback(() => {
    if (holding) {
      releaseNotice();
      return;
    }
    const snap = initialStoriesRef.current;
    const sIdx = snap.findIndex((s) => s.id === cursorIds.storyId);
    if (sIdx < 0) return;
    const story = snap[sIdx];
    const iIdx = story.items.findIndex((i) => i.id === cursorIds.itemId);
    if (iIdx > 0) {
      fireViewed(story, iIdx, "left", "backward");
      setCursorIds({ storyId: story.id, itemId: story.items[iIdx - 1].id });
      return;
    }
    const pIdx = findAdjacentStoryIndex(snap, sIdx, -1);
    if (pIdx >= 0) {
      const prevStory = snap[pIdx];
      const lastItem = prevStory.items[prevStory.items.length - 1];
      if (lastItem) {
        fireViewed(story, iIdx, "left", "backward");
        setCursorIds({ storyId: prevStory.id, itemId: lastItem.id });
      }
    }
    // else: at the very start; no-op.
  }, [cursorIds, holding, releaseNotice, fireViewed]);

  const goToNextItem = useCallback((cause?: StoryItemViewedCause) => {
    const viewedCause: StoryItemViewedCause = cause === "completed" ? "completed" : "left";
    if (holding) {
      releaseNotice();
      return;
    }
    const snap = initialStoriesRef.current;
    const sIdx = snap.findIndex((s) => s.id === cursorIds.storyId);
    if (sIdx < 0) return;
    const story = snap[sIdx];
    const iIdx = story.items.findIndex((i) => i.id === cursorIds.itemId);
    fireViewed(story, iIdx, viewedCause, "forward");
    if (iIdx < story.items.length - 1) {
      setCursorIds({ storyId: story.id, itemId: story.items[iIdx + 1].id });
      return;
    }
    // At last item — advance to the next un-muted story (forward).
    onStoryViewedRef.current?.(story.id);
    const nIdx = findAdjacentStoryIndex(snap, sIdx, 1);
    if (nIdx >= 0) {
      const nextStory = snap[nIdx];
      const firstItem = nextStory.items[0];
      if (firstItem) {
        setCursorIds({ storyId: nextStory.id, itemId: firstItem.id });
        return;
      }
    }
    // No next story — auto-close (gated by disableAutoClose per v0.2.0).
    onAutoCloseAtEndRef.current?.(story.id, cursorIds.itemId);
    if (!disableAutoCloseRef.current) onCloseRef.current();
  }, [cursorIds, holding, releaseNotice, fireViewed]);

  const goToPrevStory = useCallback(() => {
    if (holding) {
      releaseNotice();
      return;
    }
    const snap = initialStoriesRef.current;
    const sIdx = snap.findIndex((s) => s.id === cursorIds.storyId);
    if (sIdx <= 0) return;
    const pIdx = findAdjacentStoryIndex(snap, sIdx, -1);
    if (pIdx < 0) return;
    const prevStory = snap[pIdx];
    const firstItem = prevStory.items[0];
    if (firstItem) {
      const story = snap[sIdx];
      fireViewed(story, story.items.findIndex((i) => i.id === cursorIds.itemId), "left", "backward");
      // Backward — does NOT fire onStoryViewed.
      setCursorIds({ storyId: prevStory.id, itemId: firstItem.id });
    }
  }, [cursorIds, holding, releaseNotice, fireViewed]);

  const goToNextStory = useCallback(() => {
    if (holding) {
      releaseNotice();
      return;
    }
    const snap = initialStoriesRef.current;
    const sIdx = snap.findIndex((s) => s.id === cursorIds.storyId);
    if (sIdx < 0) return;
    const story = snap[sIdx];
    const nIdx = findAdjacentStoryIndex(snap, sIdx, 1);
    const nextStory = nIdx >= 0 ? snap[nIdx] : undefined;
    const firstItem = nextStory?.items[0];
    const iIdx = story.items.findIndex((i) => i.id === cursorIds.itemId);
    if (nextStory && firstItem) {
      fireViewed(story, iIdx, "left", "forward");
      onStoryViewedRef.current?.(story.id);
      setCursorIds({ storyId: nextStory.id, itemId: firstItem.id });
      return;
    }
    fireViewed(story, iIdx, "left", "forward");
    onStoryViewedRef.current?.(story.id);
    onAutoCloseAtEndRef.current?.(story.id, cursorIds.itemId);
    if (!disableAutoCloseRef.current) onCloseRef.current();
  }, [cursorIds, holding, releaseNotice, fireViewed]);

  const goToStoryIndex = useCallback((index: number) => {
    const snap = initialStoriesRef.current;
    const sIdx = Math.max(0, Math.min(index, snap.length - 1));
    const target = snap[sIdx];
    if (!target) return;
    const currentSIdx = snap.findIndex((s) => s.id === cursorIds.storyId);
    if (currentSIdx >= 0) {
      const current = snap[currentSIdx];
      const cIdx = current.items.findIndex((i) => i.id === cursorIds.itemId);
      // Direction by where the cursor goes (the target story opens on its first item); no event
      // when it lands where it already is.
      if (sIdx !== currentSIdx || cIdx > 0) {
        fireViewed(current, cIdx, "left", sIdx > currentSIdx ? "forward" : "backward");
      }
    }
    // Forward jump — fire onStoryViewed for the leaving story.
    if (sIdx > currentSIdx && currentSIdx >= 0) {
      onStoryViewedRef.current?.(snap[currentSIdx].id);
    }
    setCursorIds({
      storyId: target.id,
      itemId: target.items[0]?.id ?? "",
    });
  }, [cursorIds, fireViewed]);

  const goToItemIndex = useCallback((index: number) => {
    const snap = initialStoriesRef.current;
    const sIdx = snap.findIndex((s) => s.id === cursorIds.storyId);
    if (sIdx < 0) return;
    const story = snap[sIdx];
    const iIdx = Math.max(0, Math.min(index, story.items.length - 1));
    const item = story.items[iIdx];
    if (!item) return;
    const cIdx = story.items.findIndex((i) => i.id === cursorIds.itemId);
    if (cIdx >= 0 && cIdx !== iIdx) {
      fireViewed(story, cIdx, "left", iIdx > cIdx ? "forward" : "backward");
    }
    setCursorIds({ storyId: story.id, itemId: item.id });
  }, [cursorIds, fireViewed]);

  const reset = useCallback(
    (next: Story[]) => {
      dispatch({ kind: "reset", next });
    },
    [dispatch],
  );

  return {
    stories,
    cursor,
    isPaused,
    isMuted,
    setPaused,
    setMuted,
    goToPrevItem,
    goToNextItem,
    goToPrevStory,
    goToNextStory,
    goToStoryIndex,
    goToItemIndex,
    reset,
    dispatch,
    snapCount,
    pauseReasons: reasons,
    addPauseReason,
    removePauseReason,
    pendingRemoval,
  };
}

"use client";

import { useEffect, useRef, useState } from "react";

export interface UseStoryProgressOptions {
  /** Viewer is mounted-and-open. When false, timer is fully stopped. */
  isOpen: boolean;
  /** When true, the timer pauses but accumulator is preserved (resume continues from same %). */
  isPaused: boolean;
  /** Compound key — typically `${storyId}:${itemId}`. Any change resets the accumulator. */
  itemKey: string;
  /** Total item duration in milliseconds. */
  itemDurationMs: number;
  /** Fires once when progress reaches 100. */
  onComplete: () => void;
  /** Tick interval. Default 50ms. */
  tickMs?: number;
  /**
   * Percent (0-100) the timer should already have covered. Raises the accumulator to
   * `seedPct` of `itemDurationMs` when it is behind (never lowers it), so a hand-over from
   * another progress source (a video that errored mid-play) continues from where the bar was
   * instead of restarting at 0. Reset with the item. Default: no seed.
   */
  seedPct?: number;
}

/**
 * Accumulator-based story progress timer.
 *
 * Tracks an `accumulatedMs` accumulator across pause/resume cycles so users
 * can pause for arbitrary durations without losing playback position.
 * Naive `Date.now() - startTime` recomputes (kasder's original pattern) silently
 * advance ~50ms per pause/resume cycle. Switched to `performance.now()` here
 * for monotonic clock + immunity to NTP / DST jumps.
 */
export function useStoryProgress({
  isOpen,
  isPaused,
  itemKey,
  itemDurationMs,
  onComplete,
  tickMs = 50,
  seedPct,
}: UseStoryProgressOptions) {
  const [progress, setProgress] = useState(0);
  const [renderedItemKey, setRenderedItemKey] = useState(itemKey);
  const accumulatedRef = useRef(0);
  const startTimeRef = useRef<number | null>(null);
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
  const completedRef = useRef(false);
  const onCompleteRef = useRef(onComplete);

  useEffect(() => {
    onCompleteRef.current = onComplete;
  });

  // Reset on item change — React 19 pattern: setState during render when
  // a derivable prop changes. Refs get reset in the effect below.
  if (renderedItemKey !== itemKey) {
    setRenderedItemKey(itemKey);
    setProgress(0);
  }

  // Refs reset on item change — runs before the timer effect (declaration order).
  useEffect(() => {
    accumulatedRef.current = 0;
    completedRef.current = false;
  }, [itemKey]);

  // Hand-over seed: raise (never lower) the accumulator to the seeded share of the item.
  // Declared after the reset effect so a new item's seed lands on the cleared accumulator.
  useEffect(() => {
    if (seedPct === undefined || !(seedPct > 0)) return;
    const seeded = (Math.min(seedPct, 100) / 100) * itemDurationMs;
    if (seeded > accumulatedRef.current) accumulatedRef.current = seeded;
  }, [seedPct, itemDurationMs, itemKey]);

  useEffect(() => {
    if (!isOpen) {
      // Fully stop on close.
      accumulatedRef.current = 0;
      startTimeRef.current = null;
      if (intervalRef.current !== null) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      return;
    }

    if (isPaused) {
      // Snapshot elapsed into accumulator + clear interval.
      if (startTimeRef.current !== null) {
        accumulatedRef.current += performance.now() - startTimeRef.current;
        startTimeRef.current = null;
      }
      if (intervalRef.current !== null) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
      return;
    }

    // Run.
    startTimeRef.current = performance.now();
    intervalRef.current = setInterval(() => {
      const startedAt = startTimeRef.current;
      if (startedAt === null) return;
      const elapsed = performance.now() - startedAt + accumulatedRef.current;
      const pct = Math.min((elapsed / itemDurationMs) * 100, 100);
      setProgress(pct);
      if (pct >= 100 && !completedRef.current) {
        completedRef.current = true;
        accumulatedRef.current = 0;
        startTimeRef.current = null;
        if (intervalRef.current !== null) {
          clearInterval(intervalRef.current);
          intervalRef.current = null;
        }
        onCompleteRef.current();
      }
    }, tickMs);

    return () => {
      // Bank the elapsed time before stopping: an `itemDurationMs` change
      // mid-item (video metadata arriving) re-runs this effect, and without
      // banking the elapsed time the bar would jump back to 0. Item changes /
      // close reset the accumulator in the effects that run after this cleanup.
      if (startTimeRef.current !== null) {
        accumulatedRef.current += performance.now() - startTimeRef.current;
        startTimeRef.current = null;
      }
      if (intervalRef.current !== null) {
        clearInterval(intervalRef.current);
        intervalRef.current = null;
      }
    };
  }, [isOpen, isPaused, itemKey, itemDurationMs, tickMs]);

  // The seeded share is shown from the first frame; the timer takes over from there.
  return seedPct !== undefined && seedPct > progress ? Math.min(seedPct, 100) : progress;
}

"use client";

import { useEffect, useRef } from "react";
import { isActivatableTarget } from "../lib/is-editable-target";
import { useGlobalKeydown } from "./use-global-keydown";

export interface UseStoryKeyboardNavOptions {
  isOpen: boolean;
  onPrevItem: () => void;
  onNextItem: () => void;
  onTogglePause: () => void;
  /** Optional — Radix Dialog already handles Escape via `onOpenChange`; supply only if you want a parallel hook. */
  onClose?: () => void;
  /**
   * v0.2.0 — when false, the window keydown listener does not attach.
   * Default: true. Mirrors the `disableKeyboardNav` opt-out on
   * StoryViewerProps.
   */
  enabled?: boolean;
  /**
   * 0.6.0 (SV19) - read at key time. When it returns true the horizontal arrows swap: ArrowLeft goes
   * to the NEXT item and ArrowRight to the previous one (right-to-left reading order).
   */
  isRtl?: () => boolean;
}

/**
 * Window-scoped keyboard handlers for the story viewer.
 *
 * - ArrowLeft → onPrevItem (onNextItem under RTL)
 * - ArrowRight → onNextItem (onPrevItem under RTL)
 * - Space → onTogglePause (preventDefault to stop page scroll)
 * - Escape → onClose (when supplied; deduplicated with Radix Dialog)
 *
 * Events from editable targets (input / textarea / select / contentEditable /
 * `[role="textbox"]` / `[data-keyboard-ignore]`), IME composition and events another
 * handler already prevented are ignored (via `useGlobalKeydown`).
 *
 * Listener attaches on `isOpen=true` only and detaches on close — no leaks.
 * Refs-mirror pattern keeps the listener stable; only re-attaches on `isOpen` flip.
 */
export function useStoryKeyboardNav(opts: UseStoryKeyboardNavOptions) {
  const refs = useRef(opts);
  useEffect(() => {
    refs.current = opts;
  });

  const { isOpen, enabled = true } = opts;
  // useGlobalKeydown skips editable targets (incl. inside shadow roots), IME composition and
  // events another handler already prevented.
  useGlobalKeydown(
    (e) => {
      switch (e.key) {
        case "ArrowLeft":
        case "ArrowRight": {
          const rtl = refs.current.isRtl?.() ?? false;
          const forward = (e.key === "ArrowRight") !== rtl;
          if (forward) refs.current.onNextItem();
          else refs.current.onPrevItem();
          break;
        }
        case " ":
          // Space on a focused button/link activates that element instead.
          if (isActivatableTarget(e.target)) return;
          e.preventDefault();
          refs.current.onTogglePause();
          break;
        case "Escape":
          refs.current.onClose?.();
          break;
      }
    },
    { enabled: isOpen && enabled },
  );
}

"use client";

import { useCallback, useEffect, useReducer, useRef } from "react";
import type {
  StoryEngagementDelta,
  StoryEngagementLocalAction,
  StoryItemEngagement,
  Subscribe,
} from "../types";

// ─── Per-item engagement state ──────────────────────────────────────────

/** `null` count = withheld (the host gave none, or sent `null`): no number is rendered. */
export interface StoryItemEngagementState {
  likeCount: number | null;
  liked: boolean;
  reactionCount: number | null;
  viewerReaction: string | null;
  replyCount: number | null;
}

const DEFAULT_STATE: StoryItemEngagementState = {
  likeCount: 0,
  liked: false,
  reactionCount: 0,
  viewerReaction: null,
  replyCount: 0,
};

/** Initial state for an item: the host's `StoryItem.engagement` seed over the defaults. */
export function seedToState(seed: StoryItemEngagement | undefined): StoryItemEngagementState {
  if (!seed) return DEFAULT_STATE;
  return {
    likeCount: seed.likeCount === undefined ? 0 : seed.likeCount,
    liked: seed.liked ?? false,
    reactionCount: seed.reactionCount === undefined ? 0 : seed.reactionCount,
    viewerReaction: seed.viewerReaction ?? null,
    replyCount: seed.replyCount === undefined ? 0 : seed.replyCount,
  };
}

/** A withheld (`null`) count stays withheld under a local +1 / -1; a number moves. */
const bump = (n: number | null, by: 1 | -1): number | null =>
  n === null ? null : Math.max(0, n + by);

/**
 * Compound key for the state map. Story-viewer-01's engagement state is
 * per-(storyId, itemId) — each item in each story tracks independently.
 */
function key(storyId: string, itemId: string): string {
  return `${storyId}:${itemId}`;
}

// ─── Reducer (pure) ─────────────────────────────────────────────────────

type EngagementStateMap = Record<string, StoryItemEngagementState>;

export function storyEngagementReducer(
  state: EngagementStateMap,
  action: StoryEngagementLocalAction,
): EngagementStateMap {
  switch (action.kind) {
    case "like-toggle": {
      const k = key(action.storyId, action.itemId);
      const prev = state[k] ?? seedToState(action.seed);
      if (prev.liked === action.nextLiked) return state;
      return {
        ...state,
        [k]: {
          ...prev,
          liked: action.nextLiked,
          likeCount: bump(prev.likeCount, action.nextLiked ? 1 : -1),
        },
      };
    }
    case "reaction-select": {
      const k = key(action.storyId, action.itemId);
      const prev = state[k] ?? seedToState(action.seed);
      if (prev.viewerReaction === action.reactionKind) return state;
      // Clearing a reaction decrements; setting a new one (when none was set)
      // increments. Switching from one kind to another keeps the count stable.
      let nextCount = prev.reactionCount;
      if (action.reactionKind == null && prev.viewerReaction != null) {
        nextCount = bump(prev.reactionCount, -1);
      } else if (action.reactionKind != null && prev.viewerReaction == null) {
        nextCount = bump(prev.reactionCount, 1);
      }
      return {
        ...state,
        [k]: {
          ...prev,
          viewerReaction: action.reactionKind,
          reactionCount: nextCount,
        },
      };
    }
    case "subscribe-delta": {
      const d = action.delta;
      switch (d.kind) {
        case "like-changed": {
          const k = key(d.storyId, d.itemId);
          const prev = state[k] ?? seedToState(action.seed);
          return {
            ...state,
            [k]: {
              ...prev,
              likeCount: d.count,
              liked: d.liked ?? prev.liked,
            },
          };
        }
        case "reaction-changed": {
          const k = key(d.storyId, d.itemId);
          const prev = state[k] ?? seedToState(action.seed);
          return {
            ...state,
            [k]: {
              ...prev,
              reactionCount: d.count,
              viewerReaction:
                d.reactionKind !== undefined ? d.reactionKind : prev.viewerReaction,
            },
          };
        }
        case "reply-added": {
          const k = key(d.storyId, d.itemId);
          const prev = state[k] ?? seedToState(action.seed);
          return {
            ...state,
            [k]: { ...prev, replyCount: prev.replyCount === null ? null : prev.replyCount + 1 },
          };
        }
        // viewer-added and view-count-changed don't affect per-item engagement
        // (they're owner-overlay concerns); ignored here, handled in OwnerOverlay.
        case "viewer-added":
        case "view-count-changed":
          return state;
      }
      return state;
    }
    case "reset": {
      const k = key(action.storyId, action.itemId);
      const rest = { ...state };
      delete rest[k];
      return rest;
    }
  }
}

// ─── Hook ────────────────────────────────────────────────────────────────

export interface UseStoryEngagementStateOptions {
  /** Wired engagementSubscribe stream from story-viewer props. */
  subscribe?: Subscribe<StoryEngagementDelta>;
  /** Forwarding callback — fires for every delta the subscription emits. */
  onSubscribeDelta?: (delta: StoryEngagementDelta) => void;
  /**
   * Looks up the host's `StoryItem.engagement` seed for an item. Used when an action or a
   * realtime delta is the FIRST thing to touch an item, so it applies on top of the seed.
   */
  getSeed?: (storyId: string, itemId: string) => StoryItemEngagement | undefined;
}

export interface UseStoryEngagementStateResult {
  /**
   * Reads per-(storyId, itemId) engagement state. With no entry yet it returns the state built
   * from `seed` (the item's `engagement`), or the zero defaults when there is none.
   */
  getState: (
    storyId: string,
    itemId: string,
    seed?: StoryItemEngagement,
  ) => StoryItemEngagementState;
  /** Dispatcher for local actions (used by overlay onToggle / onSelect). Attaches the item's seed. */
  dispatch: React.Dispatch<StoryEngagementLocalAction>;
}

/**
 * Per-(storyId, itemId) engagement state hook. Subscribes to the optional
 * engagement realtime stream + reduces local actions (like / reaction toggles)
 * into a single state map.
 *
 * Mount-scoped subscribe wiring (matches the rest of the family's contract).
 */
export function useStoryEngagementState(
  opts: UseStoryEngagementStateOptions,
): UseStoryEngagementStateResult {
  const [state, rawDispatch] = useReducer(storyEngagementReducer, {});

  const onSubscribeDeltaRef = useRef(opts.onSubscribeDelta);
  const getSeedRef = useRef(opts.getSeed);
  useEffect(() => {
    onSubscribeDeltaRef.current = opts.onSubscribeDelta;
    getSeedRef.current = opts.getSeed;
  });

  const dispatch = useCallback((action: StoryEngagementLocalAction) => {
    if (action.kind === "reset") {
      rawDispatch(action);
      return;
    }
    if (action.kind === "subscribe-delta") {
      const d = action.delta;
      const seed =
        action.seed ??
        ("itemId" in d ? getSeedRef.current?.(d.storyId, d.itemId) : undefined);
      rawDispatch({ ...action, seed });
      return;
    }
    rawDispatch({
      ...action,
      seed: action.seed ?? getSeedRef.current?.(action.storyId, action.itemId),
    });
  }, []);

  const subscribe = opts.subscribe;
  useEffect(() => {
    if (!subscribe) return;
    const unsub = subscribe((delta) => {
      onSubscribeDeltaRef.current?.(delta);
      dispatch({ kind: "subscribe-delta", delta });
    });
    return unsub;
  }, [subscribe, dispatch]);

  const getState = (
    storyId: string,
    itemId: string,
    seed?: StoryItemEngagement,
  ): StoryItemEngagementState => state[key(storyId, itemId)] ?? seedToState(seed);

  return { getState, dispatch };
}

/**
 * Pure permission resolver for story-viewer v0.2.0.
 *
 * Mirrors post-card v0.3.0's `lib/permissions.ts` shape verbatim per
 * Q-V10 lock. Resolution order (most → least specific):
 *   1. `canPerformAction(action, story, item)` returning `true | false` — wins
 *   2. `permissions[canX]` per-field — `false` denies, `true` allows
 *   3. `viewerMode`-derived defaults from `PERMISSION_DEFAULTS_BY_MODE`
 *   4. Library-baseline default (legacy v0.1 mode — caller short-circuits before
 *      calling this resolver; see `lib/kebab.ts` dual-mode branch)
 *
 * Truth table (same shape as post-card):
 * | viewerMode  | permissions  | resolved matrix                                    |
 * |-------------|--------------|----------------------------------------------------|
 * | `undefined` | `undefined`  | (resolver NOT called — legacy v0.1 path)           |
 * | `undefined` | `{ ... }`    | viewer baseline + permissions override per-field   |
 * | `"owner"`   | `undefined`  | owner defaults                                     |
 * | `"owner"`   | `{ ... }`    | owner defaults + permissions override per-field    |
 * | `"viewer"`  | `undefined`  | viewer defaults                                    |
 * | `"viewer"`  | `{ ... }`    | viewer defaults + permissions override per-field   |
 */

import type {
  Story,
  StoryItem,
  StoryPermissionAction,
  StoryViewerMode,
  StoryViewerPermissions,
} from "../types";

/**
 * Library-baseline permission matrix by viewer mode. `Required<StoryViewerPermissions>`
 * ensures every field is resolved (no `undefined` leaks downstream).
 *
 * `canShare` defaults to `true` in BOTH modes (owners share their own; viewers
 * share other people's). `canModerate` defaults to `false` in BOTH — orthogonal
 * capability, never auto-derived from `viewerMode` (per Q-V11 lock — host opts
 * in explicitly via `permissions.canModerate: true` or `canPerformAction`).
 */
export const PERMISSION_DEFAULTS_BY_MODE: Record<
  StoryViewerMode,
  Required<StoryViewerPermissions>
> = {
  owner: {
    // owner-side affordances
    canSaveToHighlights: true,
    canDeleteStory: true,
    canShareToFeed: true,
    canSeeViewers: true,
    // viewer-side off for owners (they don't react to their own story)
    canLike: false,
    canReact: false,
    canReply: false,
    canShare: true,
    canDM: false,
    canReport: false,
    canBlockAuthor: false,
    canMuteAuthor: false,
    // moderation is orthogonal to viewerMode — never auto-derived
    canModerate: false,
  },
  viewer: {
    // owner-side off for viewers
    canSaveToHighlights: false,
    canDeleteStory: false,
    canShareToFeed: false,
    canSeeViewers: false,
    // viewer-side full
    canLike: true,
    canReact: true,
    canReply: true,
    canShare: true,
    canDM: true,
    canReport: true,
    canBlockAuthor: true,
    canMuteAuthor: true,
    canModerate: false,
  },
};

/**
 * Special-case map for action discriminator keys that don't auto-capitalize
 * cleanly. `dm` → `canDM` (DM as an acronym; not `canDm`). All other actions
 * use the generic `can${cap(action)}` pattern.
 */
const SPECIAL_KEYS: Partial<Record<StoryPermissionAction, keyof StoryViewerPermissions>> = {
  dm: "canDM",
};

/**
 * Map a `StoryPermissionAction` string to its `StoryViewerPermissions` matrix key.
 *
 * `"saveToHighlights"` → `"canSaveToHighlights"`, `"react"` → `"canReact"`, etc.
 * `"dm"` → `"canDM"` via SPECIAL_KEYS (preserves acronym casing).
 * Pure, no side effects.
 */
function actionToPermissionKey(
  action: StoryPermissionAction,
): keyof StoryViewerPermissions {
  if (action in SPECIAL_KEYS) return SPECIAL_KEYS[action]!;
  return `can${action.charAt(0).toUpperCase()}${action.slice(1)}` as keyof StoryViewerPermissions;
}

/**
 * Pure resolver — returns the fully-resolved permission matrix for the
 * rendering pass. Does NOT consult `canPerformAction` (that's evaluated
 * per-action by `canPerformStoryActionInternal`).
 *
 * Caller's contract: only invoke when role-aware mode is active (at least one
 * of `viewerMode` / `permissions` / `canPerformAction` is set). Legacy mode
 * short-circuits in the calling helper before this is reached.
 */
export function resolveStoryPermissions(
  viewerMode: StoryViewerMode | undefined,
  permissions: StoryViewerPermissions | undefined,
): Required<StoryViewerPermissions> {
  const base = viewerMode
    ? PERMISSION_DEFAULTS_BY_MODE[viewerMode]
    : PERMISSION_DEFAULTS_BY_MODE.viewer; // viewer baseline when viewerMode undefined but permissions set
  if (!permissions) return { ...base };
  // Skip undefined fields during merge: `permissions={{ canReact: undefined }}`
  // should fall through to the mode default, not override it with undefined.
  const result: Required<StoryViewerPermissions> = { ...base };
  for (const key of Object.keys(permissions) as (keyof StoryViewerPermissions)[]) {
    const value = permissions[key];
    if (value !== undefined) {
      result[key] = value;
    }
  }
  // `canLike` defaults to whatever `canReact` resolves to: only a host that sets it
  // explicitly gates likes separately from reactions.
  if (permissions.canLike === undefined) result.canLike = result.canReact;
  else EXPLICIT_LIKE.add(result);
  return result;
}

/**
 * Matrices whose `canLike` the host set explicitly (read off the raw `permissions` prop).
 * Equality with `canReact` cannot tell "unset" from "set to the same value", so the
 * provenance is recorded here instead of being guessed.
 */
const EXPLICIT_LIKE = new WeakSet<object>();

/**
 * Per-action resolution. Returns `true` to allow the action / `false` to deny.
 *
 * Resolution:
 *   1. `canPerformAction(action, story, item)` returning `true | false` wins
 *   2. Matrix value from `resolvedMatrix` (already includes mode defaults +
 *      permissions overrides)
 *
 * `canPerformAction` returning `undefined` falls through to step 2.
 */
export function canPerformStoryActionInternal(
  action: StoryPermissionAction,
  story: Story,
  item: StoryItem,
  resolvedMatrix: Required<StoryViewerPermissions>,
  canPerformAction:
    | ((action: StoryPermissionAction, story: Story, item: StoryItem) => boolean | undefined)
    | undefined,
): boolean {
  if (canPerformAction) {
    const result = canPerformAction(action, story, item);
    if (result !== undefined) return result;
    // `like` follows `react` unless the host set `canLike` explicitly, so a host whose
    // predicate only knows `react` keeps today's output.
    if (action === "like" && !EXPLICIT_LIKE.has(resolvedMatrix)) {
      const react = canPerformAction("react", story, item);
      if (react !== undefined) return react;
    }
  }
  return resolvedMatrix[actionToPermissionKey(action)] !== false;
}

/**
 * Build the StoryEngagementAction[] for the engagement overlay's
 * <EngagementBar variant="stacked">. Honors the resolved permissions matrix
 * + reactionKinds + per-item engagement state.
 *
 * Reaction action is only added when both `canReact` resolves true AND the
 * host supplied `reactionKinds` (per Q-V4 lock — engagement-bar v0.3.x reaction
 * kinds are host-supplied, no library defaults).
 */

import type {
  Story,
  StoryEngagementAction,
  StoryEngagementReactionKind,
  StoryItem,
  StoryPermissionAction,
  StoryViewerPermissions,
} from "../types";
import type { StoryItemEngagementState } from "../hooks/use-story-engagement-state";
import {
  canPerformStoryActionInternal,
  resolveStoryPermissions,
} from "./permissions";

export interface BuildEngagementActionsOptions {
  story: Story;
  item: StoryItem;
  state: StoryItemEngagementState;
  /** Resolved matrix from resolveStoryPermissions. */
  matrix: Required<StoryViewerPermissions>;
  canPerformAction?: (
    action: StoryPermissionAction,
    story: Story,
    item: StoryItem,
  ) => boolean | undefined;
  reactionKinds?: StoryEngagementReactionKind[];
  /** Like toggle handler — fires onLikeStory through to the consumer. */
  onLikeToggle?: (nextLiked: boolean) => void;
  /** Reaction select handler — fires onReactStory. */
  onReactSelect?: (kind: string | null) => void;
  /** Comment click handler — typically focuses the reply composer. */
  onCommentClick?: () => void;
  /** Share click handler. */
  onShareClick?: () => void;
  /** Disclosure state of the comments sheet the comment action opens (absent: no sheet). */
  commentDisclosure?: { expanded: boolean; controls: string };
  /** Disclosure state of the share sheet the share action opens (absent: no sheet). */
  shareDisclosure?: { expanded: boolean; controls: string };
}

export function buildStoryEngagementActions(
  opts: BuildEngagementActionsOptions,
): StoryEngagementAction[] {
  const canDo = (action: StoryPermissionAction) =>
    canPerformStoryActionInternal(
      action,
      opts.story,
      opts.item,
      opts.matrix,
      opts.canPerformAction,
    );

  const actions: StoryEngagementAction[] = [];

  // Like (gated by `like`, which resolves to the same answer as `react` unless the host
  // gates it separately; owners don't like their own — the matrix handles it)
  if (canDo("like")) {
    actions.push({
      kind: "like",
      count: opts.state.likeCount,
      liked: opts.state.liked,
      onToggle: opts.onLikeToggle,
    });
  }

  // Reaction — only when canReact AND reactionKinds supplied
  if (canDo("react") && opts.reactionKinds && opts.reactionKinds.length > 0) {
    actions.push({
      kind: "reaction",
      kinds: opts.reactionKinds,
      // Seeded / live total. Withheld (`null`) and zero both render no number, so a host
      // that never seeds a count sees the same bar as before.
      totalCount:
        opts.state.reactionCount !== null && opts.state.reactionCount > 0
          ? opts.state.reactionCount
          : null,
      viewerReaction: opts.state.viewerReaction,
      onSelect: opts.onReactSelect,
      clearOnTap: true, // Q-V4 lock — inherited engagement-bar v0.3 default
    });
  }

  // Comment (always shown in viewer mode; opens reply composer)
  if (canDo("reply")) {
    actions.push({
      kind: "comment",
      count:
        opts.state.replyCount !== null && opts.state.replyCount > 0
          ? opts.state.replyCount
          : undefined,
      onClick: opts.onCommentClick,
      ...opts.commentDisclosure,
    });
  }

  // Share
  if (canDo("share")) {
    actions.push({
      kind: "share",
      onClick: opts.onShareClick,
      ...opts.shareDisclosure,
    });
  }

  // Bookmark removed in v0.3.0 — stories are not bookmarkable.
  //
  // Kebab moved to header right cluster in v0.3.5 (user feedback —
  // engagement-overlay kebab was visually inconsistent and not
  // functional). The header always renders the kebab when viewerMode is
  // set + kebab items exist.

  return actions;
}

/**
 * Convenience wrapper — resolves permissions matrix + builds the actions in
 * one call. Used by story-viewer.tsx when assembling the overlay.
 */
export function buildStoryEngagementActionsWithMatrix(
  opts: Omit<BuildEngagementActionsOptions, "matrix"> & {
    viewerMode?: "owner" | "viewer";
    permissions?: StoryViewerPermissions;
  },
): StoryEngagementAction[] {
  const matrix = resolveStoryPermissions(opts.viewerMode, opts.permissions);
  return buildStoryEngagementActions({ ...opts, matrix });
}

