import { type Ref, memo } from "react";
import { cn } from "@/lib/utils";
// F-S1 cross-cat component import — absolute-with-suffix preserves through
// the shadcn 4.6.0 rewriter (Bug 3 only affects /types; /<slug>/<file> works).
import { EngagementBar } from "@/registry/components/data/engagement-bar/engagement-bar";
import type {
  ResolvedStoryViewer01Labels,
  Story,
  StoryEngagementAction,
  StoryItem,
} from "../types";

export interface EngagementOverlayProps {
  story: Story;
  item: StoryItem;
  /**
   * Resolved StoryEngagementAction[] (built via lib/engagement-actions.ts).
   * An inline copy of engagement-bar's `EngagementAction[]`, assignable to it without a
   * cast (guarded by `__tests__/engagement-types.test.ts`).
   */
  actions: StoryEngagementAction[];
  labels: ResolvedStoryViewer01Labels;
  /**
   * v0.3.5 — whether the engagement bar is currently expanded. When false,
   * the bar is hidden; when true, the icons appear with a staggered bottom-
   * to-top animation. The toggle itself lives outside this part (v0.3.7:
   * inline in the DM bar row, rendered by story-viewer.tsx).
   */
  expanded?: boolean;
  /**
   * Fires when the reaction picker opens / closes. The root turns an open picker into a
   * layer so the story pauses while it is up.
   */
  onReactionPickerOpenChange?: (open: boolean) => void;
  className?: string;
  /**
   * v0.3.5 — caller-supplied ref for the column root. story-viewer uses
   * this to detect outside-pointer events and collapse the column.
   */
  containerRef?: Ref<HTMLDivElement>;
}

/**
 * Engagement overlay — TikTok/Reels-style vertical stack on the right edge
 * of the viewer (above the DM bar). Per Q-V2 lock: variant="stacked" is the
 * default; engagement-bar v0.3.x introduced the stacked variant explicitly
 * for portrait full-screen media.
 *
 * v0.3.5 — collapsed-by-default UX. Icons hidden by default; expanding
 * triggers a staggered bottom-to-top reveal. Kebab moved out of this part
 * to the header.
 *
 * v0.3.7 — heart toggle moved out of this part to the DM bar row (rendered
 * by story-viewer.tsx). This part now ONLY renders the engagement bar
 * itself.
 *
 * Mounting gated by `viewerMode === "viewer"` AND `!disableEngagement` (the
 * caller — story-viewer.tsx — handles the gate; this part trusts the
 * caller's decision).
 */
function EngagementOverlayInner(props: EngagementOverlayProps) {
  const { expanded = false, containerRef } = props;
  return (
    <div
      ref={containerRef}
      className={cn(
        // v0.3.7: bottom-20 leaves room for the DM bar row (which sits at
        // bottom-0 with ~56px height including padding). Heart toggle lives
        // inline in the DM bar; this column only renders the icons.
        "absolute end-3 bottom-20 z-30 flex flex-col items-center gap-3 text-media-overlay-foreground",
        // Each direct child of the bar is an ActionButton; animate each.
        "[&>div>*]:transition-all [&>div>*]:duration-300 [&>div>*]:ease-out",
        // Collapsed: hidden + offset down.
        !expanded &&
          "pointer-events-none [&>div>*]:opacity-0 [&>div>*]:translate-y-4 [&>div>*]:pointer-events-none",
        // Expanded: visible + at rest.
        expanded && "[&>div>*]:opacity-100 [&>div>*]:translate-y-0",
        // Bottom-to-top stagger when expanding — last child first.
        "[&>div>*:nth-last-child(1)]:delay-0",
        "[&>div>*:nth-last-child(2)]:delay-75",
        "[&>div>*:nth-last-child(3)]:delay-150",
        "[&>div>*:nth-last-child(4)]:delay-200",
        props.className,
      )}
      aria-hidden={expanded ? undefined : "true"}
      // Collapsed, the rail is invisible and click-through; `inert` also keeps its
      // buttons out of the tab order (focusable controls inside aria-hidden).
      inert={!expanded}
    >
      <EngagementBar
        variant="stacked"
        actions={props.actions}
        labels={props.labels.engagementLabels}
        onReactionPickerOpenChange={props.onReactionPickerOpenChange}
      />
    </div>
  );
}

export const EngagementOverlay = memo(EngagementOverlayInner);
EngagementOverlay.displayName = "EngagementOverlay";

"use client";

import { memo, useCallback, useEffect, useState } from "react";
import { cn } from "@/lib/utils";
// F-S1 cross-cat component import — absolute-with-suffix preserves through
// the shadcn 4.6.0 rewriter (Bug 3 only affects /types).
import {
  CommentComposer,
  type CommentComposerHandle,
} from "@/registry/components/data/comment-thread/parts/comment-composer";
import {
  DEFAULT_STORY_VIEWER_LABELS,
  type ResolvedStoryViewer01Labels,
  type Story,
  type StoryCurrentUser,
  type StoryItem,
} from "../types";

export interface ReplyComposerProps {
  story: Story;
  item: StoryItem;
  /** Viewer identity — required for composer mount. Absent → composer hidden. */
  currentUser?: StoryCurrentUser;
  /** Submit handler — story-viewer forwards via onAddReply prop. */
  onAddReply?: (storyId: string, itemId: string, content: string) => Promise<void> | void;
  /**
   * Called with `true` while the composer is focused or holds a draft, `false`
   * otherwise (and on unmount). The viewer maps it to the `reply-focus` pause reason.
   */
  onSetPaused: (paused: boolean) => void;
  labels: ResolvedStoryViewer01Labels;
  className?: string;
  /** Optional handle ref so the parent can focus / pre-fill the composer (triggerReply). */
  composerRef?: React.Ref<CommentComposerHandle>;
  /**
   * Pre-fill request (`triggerReply(content)`). Applied once per distinct
   * `nonce`; the text lands in the composer exactly as if typed (so the story
   * auto-pauses, same as typing).
   */
  prefill?: { nonce: number; text: string } | null;
  /**
   * @deprecated v0.3.3 — Cancel button removed and engagement column
   *   redesigned as a heart-toggle reveal in v0.3.5/v0.3.7. This callback
   *   is kept as a forward-compat hook for future host-side polish (e.g.,
   *   conditional engagement reveal tied to composer focus). Currently
   *   fired but not consumed by `story-viewer.tsx`.
   */
  onActiveChange?: (active: boolean) => void;
}

/**
 * Reply composer mounted at the bottom of the viewer per Q-V1 lock (always-
 * visible Instagram-default bottom bar). Auto-pauses the story timer on
 * first character; resumes on submit / cancel.
 *
 * Mounting gated by `viewerMode === "viewer"` AND `!disableReplyComposer` AND
 * `currentUser` present — caller handles those gates. This part trusts the
 * caller's decision.
 *
 * When `currentUser` is absent, the part returns null — story-viewer.tsx
 * mounts `composerEmptyState` slot instead (sign-in CTA for unauth viewers).
 */
function ReplyComposerInner(props: ReplyComposerProps) {
  // Destructure ALL props to locals up front. `composerRef` is a ref-typed
  // prop; reading it as `props.composerRef` inside the JSX makes the React
  // Compiler's aliasing analysis treat the whole `props` object as a ref
  // container and flag every later `props.*` read as "ref access during
  // render" (known false-positive class — see blackboard lesson:
  // destructure to locals). Locals keep the analysis precise.
  const {
    story,
    item,
    currentUser,
    onAddReply,
    onSetPaused,
    labels,
    className,
    composerRef,
    onActiveChange,
    prefill,
  } = props;
  // v0.3.2 — focus + content tracking still fires `onActiveChange` for
  // host-side polish (e.g., a future heart-toggle that only reveals the
  // engagement column when composer is active). v0.3.3 stopped USING the
  // signal internally — gradient is full-width always; engagement stays
  // always visible; the Cancel button (which caused the collision) was
  // removed. The signal is kept for forward compat.
  const [hasFocus, setHasFocus] = useState(false);
  // Controlled text so triggerReply(content) can pre-fill.
  const [text, setText] = useState("");
  // Derived, so a failed send (text kept by the composer) still reads as content.
  const hasContent = text.length > 0;
  const active = hasFocus || hasContent;
  const [appliedNonce, setAppliedNonce] = useState(prefill?.nonce ?? 0);
  if (prefill && prefill.nonce !== appliedNonce) {
    setAppliedNonce(prefill.nonce);
    setText(prefill.text);
  }
  useEffect(() => {
    onActiveChange?.(active);
  }, [active, onActiveChange]);

  // The story is paused (`reply-focus`) while the composer is focused or holds a
  // draft (a pre-fill counts as a draft), and resumes when both clear. The cleanup
  // releases the reason when the composer unmounts (it is keyed per item).
  useEffect(() => {
    onSetPaused(active);
  }, [active, onSetPaused]);
  useEffect(() => () => onSetPaused(false), [onSetPaused]);

  const handleChange = useCallback((value: string) => setText(value), []);

  const handleSubmit = useCallback(
    async (content: string) => {
      await onAddReply?.(story.id, item.id, content);
    },
    [onAddReply, story.id, item.id],
  );

  if (!currentUser) return null;

  // StoryCurrentUser is structurally identical to CommentThreadCurrentUser, so it is assignable as is.
  return (
    <div
      onFocusCapture={() => setHasFocus(true)}
      onBlurCapture={() => setHasFocus(false)}
      className={cn(
        // v0.3.3: full-width gradient strip at the bottom (right-0 always).
        // z-31 keeps the input above the engagement overlay (z-30) on the
        // OS focus stack so taps reliably reach the textarea.
        // v0.3.6: tightened vertical padding (`pt-3 pb-3` was `pt-8 pb-4`).
        // v0.3.7: right padding bumped to `pr-16` so the input doesn't
        // extend under the heart toggle that now sits inline in the DM bar
        // row (rendered by story-viewer.tsx at right-3 bottom-3).
        "absolute end-0 bottom-0 start-0 z-31 ps-4 pe-16 pt-3 pb-3 pointer-events-auto",
        "bg-linear-to-t from-media-overlay via-media-overlay/70 to-transparent",
        className,
      )}
    >
      <CommentComposer
        ref={composerRef}
        currentUser={currentUser}
        value={text}
        // An explicit `replyComposerPlaceholder` wins; the nested comment-thread label applies
        // while the story label is still the default (0.6.1 — it had no effect at all).
        placeholder={
          labels.replyComposerPlaceholder === DEFAULT_STORY_VIEWER_LABELS.replyComposerPlaceholder &&
          labels.commentLabels?.composerPlaceholder !== undefined
            ? labels.commentLabels.composerPlaceholder
            : labels.replyComposerPlaceholder(story)
        }
        onChange={handleChange}
        onSubmit={handleSubmit}
        // v0.3.3: Cancel button removed per UX feedback — Instagram-canonical
        // story DM has no Cancel; engagement column stays visible. handleCancel
        // is still wired internally for future use (e.g. Escape key handler
        // on the textarea), but no Cancel button is rendered.
        // v0.3.4: removed `pr-12` — the engagement column sits at `bottom-24`
        // while the input is at `bottom-0`, so they don't overlap vertically
        // and the input can extend full width.
        // v0.3.6: override shadcn Textarea's baked-in `min-h-16` (64px) via
        // arbitrary-selector className passthrough — bring the textarea down
        // to a single-row height that matches the 8x8 avatar (`min-h-9`)
        // with tighter vertical padding. The textarea still auto-grows up
        // to `maxRows={3}` while typing.
        // F-05: the pill is a scrim of its own (not the theme's translucent input fill), so it
        // stays legible over a bright photo in the dark theme too.
        className="[&_textarea]:min-h-9 [&_textarea]:py-1.5 [&_textarea]:text-sm [&_textarea]:bg-media-overlay! [&_textarea]:text-media-overlay-foreground! [&_textarea]:border-media-overlay-foreground/40! [&_textarea]:placeholder:text-media-overlay-foreground/70!"
        submitOnEnter
        minRows={1}
        maxRows={3}
        ariaLabel={labels.replyAriaLabel(story)}
        labels={
          labels.commentLabels
            ? {
                composerPlaceholder: labels.commentLabels.composerPlaceholder,
                composerSend: labels.commentLabels.composerSend ?? labels.replyComposerSend,
                composerCancel: labels.commentLabels.composerCancel ?? labels.replyComposerCancel,
                postFailed: labels.commentLabels.postFailed ?? labels.replyFailed,
              }
            : {
                composerSend: labels.replyComposerSend,
                composerCancel: labels.replyComposerCancel,
                postFailed: labels.replyFailed,
              }
        }
        // 0.6.1 (comment-thread 0.4.0): a rejected `onAddReply` keeps the text and shows the
        // composer's alert; styled as a media scrim so it reads over a bright photo.
        errorClassName="mt-1 w-fit rounded-md bg-media-overlay/80 px-2 py-0.5 text-xs text-media-overlay-foreground"
      />
    </div>
  );
}

export const ReplyComposer = memo(ReplyComposerInner);
ReplyComposer.displayName = "ReplyComposer";

"use client";

import { memo, useCallback, useEffect, useRef, useState } from "react";
import { Eye, X } from "lucide-react";
import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";
import { resolveLocale } from "../lib/relative-time";
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar";
import type {
  ResolvedStoryViewer01Labels,
  Story,
  StoryItem,
  StoryViewersPage,
  ViewerListItem,
} from "../types";

export interface OwnerOverlayProps {
  story: Story;
  item: StoryItem;
  /**
   * Pages the viewers of the current item: `(item.id, null)` on first open, then the
   * previous `nextCursor` for each "load more". A rejection shows a Retry row.
   */
  onLoadViewers?: (itemId: string, cursor: string | null) => Promise<StoryViewersPage>;
  labels: ResolvedStoryViewer01Labels;
  /** Locale for the view count (`Intl.NumberFormat`); invalid / absent → `"en"`. */
  locale?: string;
  className?: string;
  /**
   * Internal (not exported from the barrel): lets the root own the viewers
   * list's open state so it counts as a layer (pauses the timer, closes on
   * Escape). Uncontrolled when omitted.
   */
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}

function initials(name: string): string {
  return (
    name
      .trim()
      .split(/\s+/)
      .map((part) => part[0]?.toUpperCase() ?? "")
      .slice(0, 2)
      .join("") || "?"
  );
}

/**
 * Owner overlay — bottom-anchored view-count chip + tap-to-expand viewers
 * list panel. Mounts only when `viewerMode === "owner"` + `!disableOwnerOverlay`.
 *
 * Per Q-V5 hybrid lock: count is eager (`item.viewerCount`, falling back to
 * `story.viewerCount`; `null` = no number), users list is lazy and paged
 * (`onLoadViewers(itemId, cursor)` on first tap, then on each "load more"; a
 * rejection shows Retry). Optional eager seed via `story.viewers`
 * short-circuits the fetch. The list resets when the current item changes.
 *
 * The expanded panel renders avatars + names inline (a simple list — not the
 * cross-cat LikersStrip — to keep the F-S1 surface minimal; LikersStrip can
 * be wired via `renderOwnerOverlay` slot if the host wants the swipable
 * variant).
 */
function OwnerOverlayInner(props: OwnerOverlayProps) {
  // This item's count wins (`null` = withheld); the story's is the fallback.
  const itemCount = props.item.viewerCount;
  const storyCount = props.story.viewerCount;
  const countValue: number | null =
    itemCount !== undefined
      ? itemCount
      : storyCount !== undefined
        ? storyCount
        : (props.story.viewers?.length ?? 0);
  const [localOpen, setLocalOpen] = useState(false);
  const open = props.open ?? localOpen;
  const { onOpenChange } = props;
  const setOpen = useCallback(
    (next: boolean) => {
      setLocalOpen(next);
      onOpenChange?.(next);
    },
    [onOpenChange],
  );
  const seeded = props.story.viewers !== undefined;
  const [viewers, setViewers] = useState<ViewerListItem[]>(props.story.viewers ?? []);
  const [nextCursor, setNextCursor] = useState<string | null>(null);
  const [status, setStatus] = useState<"idle" | "loading" | "error">("idle");
  // The cursor the failed / in-flight request uses; Retry repeats exactly that call.
  const [pendingCursor, setPendingCursor] = useState<string | null>(null);
  const [didFetch, setDidFetch] = useState(false);
  // Bumped on every item change so a response for a previous item is dropped.
  const requestRef = useRef(0);

  // The list belongs to ONE item: reset it when the current item changes (cursor
  // navigation). Render-time prev-props adjustment (React docs "adjusting state when a
  // prop changes") instead of an effect — same reset semantics without the
  // set-state-in-effect cascading re-render (and no one-frame stale panel).
  const itemKey = `${props.story.id}:${props.item.id}`;
  const [prevItemKey, setPrevItemKey] = useState(itemKey);
  if (prevItemKey !== itemKey) {
    setPrevItemKey(itemKey);
    // The root closes a controlled list on the same cursor change.
    setLocalOpen(false);
    setViewers(props.story.viewers ?? []);
    setNextCursor(null);
    setPendingCursor(null);
    setStatus("idle");
    setDidFetch(false);
  }
  useEffect(() => {
    requestRef.current += 1;
  }, [itemKey]);

  const { onLoadViewers } = props;
  const itemId = props.item.id;
  const loadPage = useCallback(
    async (cursor: string | null) => {
      if (!onLoadViewers) return;
      const token = ++requestRef.current;
      setStatus("loading");
      setPendingCursor(cursor);
      try {
        const page = await onLoadViewers(itemId, cursor);
        if (token !== requestRef.current) return;
        setViewers((prev) => {
          if (cursor === null) return page.items;
          const seen = new Set(prev.map((v) => v.id));
          return prev.concat(page.items.filter((v) => !seen.has(v.id)));
        });
        setNextCursor(page.nextCursor);
        setDidFetch(true);
        setStatus("idle");
      } catch {
        if (token !== requestRef.current) return;
        setStatus("error");
      }
    },
    [onLoadViewers, itemId],
  );

  const handleToggle = useCallback(() => {
    if (open) {
      setOpen(false);
      return;
    }
    setOpen(true);
    if (!seeded && onLoadViewers && status === "idle" && !didFetch) {
      void loadPage(null);
    }
  }, [open, setOpen, seeded, onLoadViewers, status, didFetch, loadPage]);

  // A tap outside the list dismisses it (no backdrop); focus returns to the
  // opener on close. The chip carries `data-story-layer` so tapping it only
  // toggles (via its click), never dismisses-then-reopens.
  const openerRef = useRef<HTMLElement | null>(null);
  useEffect(() => {
    if (open) {
      const active = document.activeElement;
      openerRef.current =
        active instanceof HTMLElement && active !== document.body ? active : null;
      const onDown = (e: PointerEvent) => {
        const target = e.target;
        if (target instanceof Element && target.closest('[data-story-layer="viewers"]')) return;
        setOpen(false);
      };
      document.addEventListener("pointerdown", onDown);
      return () => document.removeEventListener("pointerdown", onDown);
    }
    const opener = openerRef.current;
    openerRef.current = null;
    if (opener && opener.isConnected) {
      const active = document.activeElement;
      if (!active || active === document.body) opener.focus({ preventScroll: true });
    }
    return undefined;
  }, [open, setOpen]);

  const timeStr = props.labels.formatTime(new Date(props.item.createdAt ?? props.story.createdAt));
  const formattedCount =
    countValue === null ? "" : new Intl.NumberFormat(resolveLocale(props.locale)).format(countValue);
  // A withheld (`null`) count renders no number and reaches no accessible name.
  const ariaLabel =
    countValue === null
      ? `${props.labels.viewersHeading} · ${timeStr}`
      : props.labels.viewerCountLabel(countValue, timeStr, formattedCount);
  const retry = () => void loadPage(pendingCursor);

  return (
    <>
      {/* View-count chip — bottom-left of viewer (replaces reply composer in owner mode). */}
      <div
        className={cn(
          "absolute inset-x-0 bottom-0 z-30 flex items-center px-4 pb-4 pt-8",
          "bg-linear-to-t from-media-overlay via-media-overlay/70 to-transparent",
          props.className,
        )}
      >
        <button
          type="button"
          data-story-layer="viewers"
          onClick={handleToggle}
          className={cn(
            buttonVariants({ variant: "ghost", size: "sm" }),
            "h-11 text-media-overlay-foreground hover:bg-media-overlay-foreground/20 hover:text-media-overlay-foreground",
          )}
          aria-label={ariaLabel}
          aria-expanded={open}
        >
          <Eye className="me-2 h-4 w-4" />
          {countValue === null ? null : <span className="font-semibold">{formattedCount}</span>}
          <span className={cn("text-media-overlay-foreground/70", countValue !== null && "ms-2")}>
            {countValue === null ? timeStr : `· ${timeStr}`}
          </span>
        </button>
      </div>

      {/* Viewers panel — bottom-anchored sheet that slides up. */}
      {open ? (
        <div data-story-layer="viewers" className="absolute inset-x-0 bottom-0 z-40 max-h-[60%] overflow-hidden rounded-t-2xl bg-card text-foreground shadow-2xl">
          <div className="flex items-center justify-between border-b border-border px-4 py-3">
            <h3 className="text-sm font-semibold">{props.labels.viewersHeading}</h3>
            <button
              type="button"
              onClick={() => setOpen(false)}
              className={cn(
                buttonVariants({ variant: "ghost", size: "icon" }),
                "h-9 w-9",
              )}
              aria-label={props.labels.close}
            >
              <X className="h-4 w-4" />
            </button>
          </div>
          <div className="max-h-[50vh] overflow-y-auto">
            {viewers.length === 0 && status === "loading" ? (
              <p className="px-4 py-6 text-center text-sm text-muted-foreground">
                {props.labels.viewersLoading}
              </p>
            ) : viewers.length === 0 && status === "error" ? (
              <ViewersError labels={props.labels} onRetry={retry} />
            ) : viewers.length === 0 ? (
              <p className="px-4 py-6 text-center text-sm text-muted-foreground">
                {props.labels.viewersEmpty}
              </p>
            ) : (
              <>
                <ul className="flex flex-col">
                  {viewers.map((viewer) => (
                    <li
                      key={viewer.id}
                      className="flex items-center gap-3 border-b border-border/30 px-4 py-2 last:border-b-0"
                    >
                      <Avatar className="h-8 w-8 shrink-0">
                        {viewer.avatar ? <AvatarImage src={viewer.avatar} alt="" /> : null}
                        <AvatarFallback className="text-xs">{initials(viewer.name)}</AvatarFallback>
                      </Avatar>
                      <span className="flex-1 text-sm font-medium">{viewer.name}</span>
                      {viewer.viewedAt ? (
                        <span className="text-xs text-muted-foreground">
                          {props.labels.formatTime(new Date(viewer.viewedAt))}
                        </span>
                      ) : null}
                    </li>
                  ))}
                </ul>
