/**
 * Default story kebab items builder. Dual-mode helper mirroring
 * post-card v0.3.0's `defaultPostKebabActions`:
 *
 *   - **Legacy mode (v0.1 compat):** when `viewerMode` / `permissions` /
 *     `canPerformAction` are ALL undefined, returns only the host's
 *     `extraKebabActions` (0.7.0; `[]` without them). The kebab renders whenever
 *     the final list has a visible item.
 *
 *   - **Role-aware mode (v0.2.0):** when ANY of the three role-aware args is
 *     set, the helper calls `resolveStoryPermissions` +
 *     `canPerformStoryActionInternal` to produce role-appropriate items per
 *     the resolution order in `lib/permissions.ts`.
 *
 * Owner mode: Save to highlights / Delete story / Share to feed / Copy link.
 * Viewer mode: Copy link / Mute author / Block author / Report (destructive
 * at end).
 * Moderator section: only when `canModerate` resolves true + `moderatorActions`
 * supplied. First moderator item carries `separatorBefore: true`.
 *
 * `kebabActions` full-takeover bypasses this entirely (handled in story-viewer.tsx
 * before this is called).
 */

import type { ReactNode } from "react";
import type {
  Story,
  StoryItem,
  StoryItemTarget,
  StoryKebabMenuItem,
  StoryPermissionAction,
  StoryViewerLabels,
  StoryViewerMode,
  StoryViewerPermissions,
} from "../types";
import {
  canPerformStoryActionInternal,
  resolveStoryPermissions,
} from "./permissions";

export interface DefaultStoryKebabHandlers {
  /** Owner-side: save the current item to highlights. Receives `{ story, item }`. */
  onSaveToHighlights?: (target: StoryItemTarget) => void;
  /** Owner-side: delete the current item. Receives `{ story, item }`. */
  onDeleteStory?: (target: StoryItemTarget) => void;
  /** Owner-side: share the current item to the feed. Receives `{ story, item }`. */
  onShareToFeed?: (target: StoryItemTarget) => void;
  /** Viewer-side: report the current item. Receives `{ story, item }`. */
  onReport?: (target: StoryItemTarget) => void;
  /** Viewer-side: block author. */
  onBlockAuthor?: (authorId: string) => void;
  /** Viewer-side: mute author. */
  onMuteAuthor?: (authorId: string) => void;
  /** Common: copy a link to the current item. Receives `{ story, item }`. */
  onCopyLink?: (target: StoryItemTarget) => void;
  /** Whether the story is currently saved to highlights (toggles label). */
  isSavedToHighlights?: boolean;
}

export interface BuildStoryKebabActionsOptions {
  story: Story;
  item: StoryItem;
  handlers: DefaultStoryKebabHandlers;
  labels: Partial<
    Pick<
      Required<StoryViewerLabels>,
      | "saveToHighlights"
      | "unsaveFromHighlights"
      | "deleteStory"
      | "shareToFeed"
      | "report"
      | "blockAuthor"
      | "muteAuthor"
      | "copyLink"
    >
  >;
  viewerMode?: StoryViewerMode;
  permissions?: StoryViewerPermissions;
  canPerformAction?: (
    action: StoryPermissionAction,
    story: Story,
    item: StoryItem,
  ) => boolean | undefined;
  /** Optional moderator section supplier (additive — does NOT replace defaults). */
  moderatorActions?: (story: Story, item: StoryItem) => StoryKebabMenuItem[];
  /**
   * 0.7.0 - items appended after the defaults and the moderator section; not permission-gated.
   * They are the whole menu when no role-aware arg is set (the kebab has no defaults then).
   */
  extraActions?: (story: Story, item: StoryItem) => StoryKebabMenuItem[];
  /** Optional icons for each canonical action (host can override). */
  icons?: Partial<Record<
    | "saveToHighlights"
    | "deleteStory"
    | "shareToFeed"
    | "copyLink"
    | "muteAuthor"
    | "blockAuthor"
    | "report",
    ReactNode
  >>;
}

/** 0.7.0 - drops `hidden` items (every kebab list goes through this). */
export function visibleKebabItems(items: StoryKebabMenuItem[]): StoryKebabMenuItem[] {
  return items.some((i) => i.hidden) ? items.filter((i) => !i.hidden) : items;
}

export function defaultStoryKebabActions(
  opts: BuildStoryKebabActionsOptions,
): StoryKebabMenuItem[] {
  const extras = visibleKebabItems(opts.extraActions?.(opts.story, opts.item) ?? []);
  const roleAwareMode =
    opts.viewerMode !== undefined ||
    opts.permissions !== undefined ||
    opts.canPerformAction !== undefined;

  // Legacy mode — no default items; only the host's extras (0.7.0).
  if (!roleAwareMode) return extras;

  const matrix = resolveStoryPermissions(opts.viewerMode, opts.permissions);
  const canDo = (action: StoryPermissionAction) =>
    canPerformStoryActionInternal(action, opts.story, opts.item, matrix, opts.canPerformAction);

  const items: StoryKebabMenuItem[] = [];

  // ─── Owner-side items ─────────────────────────────────────────────────
  if (canDo("saveToHighlights") && opts.handlers.onSaveToHighlights) {
    items.push({
      label: opts.handlers.isSavedToHighlights
        ? (opts.labels.unsaveFromHighlights ?? "Remove from highlights")
        : (opts.labels.saveToHighlights ?? "Save to highlights"),
      icon: opts.icons?.saveToHighlights,
      onClick: () => opts.handlers.onSaveToHighlights!({ story: opts.story, item: opts.item }),
    });
  }
  if (canDo("shareToFeed") && opts.handlers.onShareToFeed) {
    items.push({
      label: opts.labels.shareToFeed ?? "Share to feed",
      icon: opts.icons?.shareToFeed,
      onClick: () => opts.handlers.onShareToFeed!({ story: opts.story, item: opts.item }),
    });
  }

  // ─── Common items ─────────────────────────────────────────────────────
  if (opts.handlers.onCopyLink) {
    items.push({
      label: opts.labels.copyLink ?? "Copy link",
      icon: opts.icons?.copyLink,
      onClick: () => opts.handlers.onCopyLink!({ story: opts.story, item: opts.item }),
    });
  }

  // ─── Moderator section (additive; gated by canModerate + moderatorActions) ──
  if (canDo("moderate") && opts.moderatorActions) {
    const modItems = visibleKebabItems(opts.moderatorActions(opts.story, opts.item));
    if (modItems.length > 0) {
      // First moderator item carries `separatorBefore: true` (visual section break).
      items.push({ ...modItems[0], separatorBefore: true });
      for (let i = 1; i < modItems.length; i++) {
        items.push(modItems[i]);
      }
    }
  }

  // ─── Viewer-side items (destructive at the bottom) ───────────────────
  if (canDo("muteAuthor") && opts.handlers.onMuteAuthor) {
    items.push({
      label: opts.labels.muteAuthor ?? "Mute author",
      icon: opts.icons?.muteAuthor,
      onClick: () => opts.handlers.onMuteAuthor!(opts.story.userId),
    });
  }
  if (canDo("blockAuthor") && opts.handlers.onBlockAuthor) {
    items.push({
      label: opts.labels.blockAuthor ?? "Block author",
      icon: opts.icons?.blockAuthor,
      destructive: true,
      onClick: () => opts.handlers.onBlockAuthor!(opts.story.userId),
    });
  }
  if (canDo("report") && opts.handlers.onReport) {
    items.push({
      label: opts.labels.report ?? "Report",
      icon: opts.icons?.report,
      destructive: true,
      onClick: () => opts.handlers.onReport!({ story: opts.story, item: opts.item }),
    });
  }

  // ─── Owner destructive (Delete — always last) ─────────────────────────
  if (canDo("deleteStory") && opts.handlers.onDeleteStory) {
    items.push({
      label: opts.labels.deleteStory ?? "Delete story",
      icon: opts.icons?.deleteStory,
      destructive: true,
      onClick: () => opts.handlers.onDeleteStory!({ story: opts.story, item: opts.item }),
    });
  }

  return [...items, ...extras];
}

import type { KeyboardEvent } from "react";

const TABBABLE =
  'a[href], button:not([disabled]), input:not([disabled]):not([type="hidden"]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"]), [contenteditable="true"]';

function tabbablesIn(root: HTMLElement): HTMLElement[] {
  return Array.from(root.querySelectorAll<HTMLElement>(TABBABLE)).filter(
    (el) => !el.closest("[inert]") && !el.closest('[aria-hidden="true"]') && isRendered(el, root),
  );
}

/** Not `display: none` / `visibility: hidden` (e.g. the dialog's CSS-hidden built-in close button). */
function isRendered(el: HTMLElement, root: HTMLElement): boolean {
  if (typeof getComputedStyle !== "function") return true;
  if (getComputedStyle(el).visibility === "hidden") return false;
  for (let n: HTMLElement | null = el; n; n = n.parentElement) {
    if (getComputedStyle(n).display === "none") return false;
    if (n === root) break;
  }
  return true;
}

/**
 * Keeps Tab / Shift+Tab inside a layer (bottom sheet, actions menu): from the
 * last tabbable Tab wraps to the first, and Shift+Tab from the first (or from
 * the layer itself) wraps to the last. Spread as the layer root's `onKeyDown`.
 *
 * The dialog's own focus scope can't do this here: everything behind the layer
 * is `inert`, but the scope's first / last candidates ignore `inert`, so Tab
 * from the layer's last control would leave the page instead of wrapping.
 */
export function wrapTabWithinLayer(e: KeyboardEvent<HTMLElement>) {
  if (e.key !== "Tab" || e.defaultPrevented) return;
  const root = e.currentTarget;
  const items = tabbablesIn(root);
  const active = document.activeElement;
  if (items.length === 0) {
    e.preventDefault();
    root.focus({ preventScroll: true });
    return;
  }
  const first = items[0];
  const last = items[items.length - 1];
  if (e.shiftKey && (active === first || active === root)) {
    e.preventDefault();
    last.focus({ preventScroll: true });
  } else if (!e.shiftKey && active === last) {
    e.preventDefault();
    first.focus({ preventScroll: true });
  }
}

/**
 * True when a keyboard event's target is somewhere the user is typing (or
 * otherwise owns the keys): input / textarea / select, contentEditable,
 * `[role="textbox"]`, widgets that own the arrow keys (`slider`, `spinbutton`,
 * `combobox`, `listbox`), or anything inside a `[data-keyboard-ignore]` subtree.
 * Window-level shortcuts must stand down for these.
 */
export function isEditableTarget(target: EventTarget | null): boolean {
  if (!target || typeof (target as Element).closest !== "function") return false;
  const el = target as HTMLElement;
  const tag = el.tagName;
  if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT") return true;
  if (el.isContentEditable) return true;
  return (
    el.closest(
      '[contenteditable=""], [contenteditable="true"], [role="textbox"], [role="slider"], [role="spinbutton"], [role="combobox"], [role="listbox"], [data-keyboard-ignore]',
    ) !== null
  );
}

/** True for focusable activators that own Space/Enter themselves. */
export function isActivatableTarget(target: EventTarget | null): boolean {
  if (!target || typeof (target as Element).closest !== "function") return false;
  return (
    (target as HTMLElement).closest(
      'button, a[href], [role="button"], [role="link"], [role="menuitem"], summary',
    ) !== null
  );
}

/**
 * 0.7.0 (SV-3) - off-DOM warm-up of the NEXT item's media. No node is ever mounted for it:
 * an image is fetched + decoded through `new Image()`, a video loads its metadata through a
 * detached `<video preload="metadata">` that is torn down when it is no longer the next item.
 * Browser-only: nothing here may run during render / SSR (the caller invokes it from an effect).
 */

export interface PreloadTarget {
  key: string;
  type: "image" | "video";
  url: string;
  srcSet?: string;
  sizes?: string;
}

export interface MediaPreloader {
  /** Warm `target` (once per key) and release every other warmed video. `null` = release all videos. */
  sync: (target: PreloadTarget | null) => void;
  /** Release everything and forget what was warmed. */
  dispose: () => void;
}

/** `navigator.connection.saveData` (Data Saver). Safe on any environment. */
export function dataSaverOn(): boolean {
  if (typeof navigator === "undefined") return false;
  const conn = (navigator as Navigator & { connection?: { saveData?: boolean } }).connection;
  return !!conn?.saveData;
}

function releaseVideo(el: HTMLVideoElement) {
  try {
    el.removeAttribute("src");
    el.load();
  } catch {
    // jsdom / exotic environments: nothing to release.
  }
}

export function createMediaPreloader(): MediaPreloader {
  const images = new Set<string>();
  const videos = new Map<string, HTMLVideoElement>();

  const releaseVideosExcept = (keep: string | null) => {
    for (const [key, el] of videos) {
      if (key === keep) continue;
      releaseVideo(el);
      videos.delete(key);
    }
  };

  return {
    sync(target) {
      releaseVideosExcept(target && target.type === "video" ? target.key : null);
      if (!target) return;
      if (target.type === "image") {
        const id = `${target.key}|${target.url}`;
        if (images.has(id)) return;
        images.add(id);
        if (typeof Image === "undefined") return;
        const img = new Image();
        if (target.srcSet) img.srcset = target.srcSet;
        if (target.sizes) img.sizes = target.sizes;
        img.src = target.url;
        if (typeof img.decode === "function") img.decode().catch(() => {});
        return;
      }
      if (videos.has(target.key) || typeof document === "undefined") return;
      const el = document.createElement("video");
      el.preload = "metadata";
      el.muted = true;
      el.src = target.url;
      videos.set(target.key, el);
    },
    dispose() {
      releaseVideosExcept(null);
      images.clear();
    },
  };
}

"use client";

import { useEffect, useState, useSyncExternalStore } from "react";
import { createPortal } from "react-dom";
import type { Story, StoryBackdropContext, StoryItem } from "../types";

export interface AmbientBackdropProps {
  /** Only while the viewer is open. */
  open: boolean;
  story: Story;
  item: StoryItem;
  /** `"ambient"` draws the blurred item; anything else draws nothing of its own (the dialog overlay stays). */
  mode?: "dim" | "ambient";
  /** The image URL the stage loaded (`currentSrc`), once it loaded. */
  src?: string;
  /** The video poster, when the item is a video and has one. */
  poster?: string;
  isReady: boolean;
  /**
   * The current item is still loading (not ready, not unavailable). The image already shown stays
   * until the item is ready, so the change cross-fades instead of passing through the dim overlay.
   */
  loading?: boolean;
  reducedMotion: boolean;
  /** Wins over `mode`; rendered in the same layer (also under reduced motion). */
  renderBackdrop?: (story: Story, item: StoryItem, ctx: StoryBackdropContext) => React.ReactNode;
}

const FADE_MS = 300;
const noopSubscribe = () => () => {};

/**
 * 0.7.0 (SV-2) - desktop backdrop. A fixed, full-window layer portalled to `document.body`, BELOW
 * the dialog overlay (shadcn's overlay + content are `z-50`; this is `z-40`), click-through and
 * hidden from assistive tech, shown from `md` up (the card is full screen below that). Ambient mode
 * reuses the URL the stage already loaded - it never requests a neighbour's media.
 */
export function AmbientBackdrop({
  open,
  story,
  item,
  mode,
  src,
  poster,
  isReady,
  loading = false,
  reducedMotion,
  renderBackdrop,
}: AmbientBackdropProps) {
  const client = useSyncExternalStore(noopSubscribe, () => true, () => false);

  const ambient = open && mode === "ambient" && !renderBackdrop && !reducedMotion;
  const url = ambient && isReady ? (item.type === "video" ? poster : src) : undefined;
  // While the next item loads, the image already shown holds (it is the item just left, never a
  // neighbour fetched for the backdrop); a ready item then cross-fades over it.
  const hold = ambient && loading;

  // Cross-fade: the previous image stays under the new one for one fade, then is dropped.
  const [layers, setLayers] = useState<string[]>([]);
  const [prevUrl, setPrevUrl] = useState<string | undefined>(undefined);
  if (!hold && prevUrl !== url) {
    setPrevUrl(url);
    setLayers(url ? (prevUrl && layers.includes(prevUrl) ? [prevUrl, url] : [url]) : []);
  }
  useEffect(() => {
    if (layers.length < 2) return;
    const t = window.setTimeout(() => setLayers((l) => l.slice(-1)), FADE_MS);
    return () => window.clearTimeout(t);
  }, [layers]);

  if (!client || !open) return null;

  let content: React.ReactNode = null;
  if (renderBackdrop) {
    content = renderBackdrop(story, item, { src, poster, isReady, reducedMotion });
  } else if (layers.length) {
    content = (
      <>
        {layers.map((layerUrl) => (
          <img
            key={layerUrl}
            src={layerUrl}
            alt=""
            draggable={false}
            data-story-backdrop-image=""
            className="absolute inset-0 h-full w-full scale-110 object-cover blur-3xl animate-in fade-in-0 duration-300"
          />
        ))}
        <div className="absolute inset-0 bg-media-overlay" />
      </>
    );
  }
  if (!content) return null;

  return createPortal(
    <div
      aria-hidden="true"
      data-story-backdrop=""
      className="pointer-events-none fixed inset-0 z-40 hidden overflow-hidden md:block"
    >
      {content}
    </div>,
    document.body,
  );
}

