 * area:
 *   - Collapsed: small rounded chip in the top-right (link icon + host
 *     domain) — minimal visual footprint.
 *   - Expanded: the chip stays, plus a wider banner slides down below it
 *     with the host domain + the CTA button + a close X. Tap the chip
 *     again or X to collapse.
 *   - The actual link/anchor is rendered on the CTA button inside the
 *     expanded banner; tapping the chip alone does NOT navigate — it
 *     reveals the banner. This matches Instagram-canonical link-sticker UX.
 *
 * Polymorphic root via `linkComponent`. `target="_blank"` +
 * `rel="noopener noreferrer"` are applied ONLY when the root is the
 * default `"a"`. If `onLinkClick` is supplied, it fires alongside the
 * default href navigation (host can `preventDefault` inside the handler).
 *
 * Resets to collapsed on cursor change (caller controls mount/unmount via
 * key on the storyId+itemId pair effectively because the part is mounted
 * conditionally on `item.link`; story-viewer.tsx unmounts + remounts
 * across items naturally).
 */
export function LinkCta({
  item,
  open,
  onOpenChange,
  linkComponent: LinkComponent = "a",
  onLinkClick,
  labels,
  story,
}: LinkCtaProps) {
  const [localExpanded, setLocalExpanded] = useState(false);
  const expanded = open ?? localExpanded;
  const setExpanded = (next: boolean | ((prev: boolean) => boolean)) => {
    const value = typeof next === "function" ? next(expanded) : next;
    setLocalExpanded(value);
    onOpenChange?.(value);
  };
  const containerRef = useRef<HTMLDivElement | null>(null);
  const drawerRef = useRef<HTMLDivElement | null>(null);
  const openerRef = useRef<HTMLElement | null>(null);

  // Outside-pointer-down collapses the drawer; focus returns to the opener
  // (the chip) when it closes by any route.
  useEffect(() => {
    if (expanded) {
      const active = document.activeElement;
      openerRef.current =
        active instanceof HTMLElement && active !== document.body ? active : null;
      const handler = (e: PointerEvent) => {
        const target = e.target as Node | null;
        if (containerRef.current && target && !containerRef.current.contains(target)) {
          setLocalExpanded(false);
          onOpenChange?.(false);
        }
      };
      document.addEventListener("pointerdown", handler);
      return () => document.removeEventListener("pointerdown", handler);
    }
    const opener = openerRef.current;
    openerRef.current = null;
    if (opener && opener.isConnected) {
      const active = document.activeElement;
      if (!active || active === document.body || drawerRef.current?.contains(active)) {
        opener.focus({ preventScroll: true });
      }
    }
    return undefined;
  }, [expanded, onOpenChange]);

  if (!item.link) return null;
  const isDefaultAnchor = LinkComponent === "a";

  // Parse host for the chip subtitle. Falls back to the raw URL.
  let host = "";
  try {
    host = new URL(item.link.url).host;
  } catch {
    host = item.link.url;
  }

  const handleNavClick = onLinkClick
    ? () => onLinkClick(story.id, item.id, item.link!.url)
    : undefined;
  const anchorAttrs = isDefaultAnchor
    ? {
        target: "_blank" as const,
        rel: "noopener noreferrer" as const,
      }
    : {};
  const ctaProps: ComponentProps<"a"> = {
    href: item.link.url,
    onClick: handleNavClick,
    className: cn(
      buttonVariants({ variant: "default", size: "default" }),
      "h-10 w-full text-sm font-semibold",
    ),
    ...anchorAttrs,
  };

  const ctaLabel = item.link.cta ?? labels.openLink;

  return (
    <div
      ref={containerRef}
      data-story-layer="link"
      // ProgressBars sit at top z-20 + ViewerHeader at top z-20 with `top-4`.
      // Place the chip at `top-16` so it sits just under the header strip.
      className="pointer-events-auto absolute top-16 end-3 z-25 flex flex-col items-end gap-2"
    >
      {/* Chip — always visible while the link is set. Tapping toggles the
          drawer below. */}
      <button
        type="button"
        onClick={() => setExpanded((v) => !v)}
        aria-expanded={expanded ? "true" : "false"}
        className={cn(
          "flex items-center gap-2 rounded-full bg-media-overlay/80 px-3 py-1.5 text-xs font-medium text-media-overlay-foreground",
          "backdrop-blur-sm transition-colors",
          "hover:bg-media-overlay focus-visible:bg-media-overlay focus-visible:outline-none",
          "focus-visible:ring-2 focus-visible:ring-media-overlay-foreground/40",
        )}
      >
        <LinkIcon className="h-3.5 w-3.5" />
        <span className="max-w-32 truncate">{host}</span>
        {/* 0.7.0 - no `aria-label` (it did not contain the visible host text): the name is the
            visible text plus the CTA, read after it. */}
        <span className="sr-only">{ctaLabel}</span>
      </button>
      {/* Drawer — slides down + fades in when expanded. Closes via the X
          button (top-right of the drawer) or outside-pointer-down. */}
      <div
        className={cn(
          "w-72 max-w-[calc(100vw-1.5rem)] rounded-xl bg-background text-foreground shadow-2xl",
          "origin-top-right transition-all duration-200 ease-out",
          expanded
            ? "scale-100 opacity-100 translate-y-0"
            : "pointer-events-none scale-95 opacity-0 -translate-y-2",
        )}
        aria-hidden={expanded ? undefined : "true"}
        // Closed: out of the tab order and the accessibility tree.
        inert={!expanded}
        ref={drawerRef}
      >
        <div className="flex items-center justify-between gap-2 border-b border-border px-3 py-2">
          <div className="flex min-w-0 flex-1 items-center gap-2">
            <LinkIcon className="h-3.5 w-3.5 shrink-0 text-muted-foreground" />
            <span className="min-w-0 truncate text-xs text-muted-foreground">
              {host}
            </span>
          </div>
          <button
            type="button"
            onClick={() => setExpanded(false)}
            aria-label={labels.linkCloseLabel}
            className={cn(
              "flex h-7 w-7 shrink-0 items-center justify-center rounded-full",
              "text-muted-foreground transition-colors hover:bg-muted hover:text-foreground",
              "focus-visible:bg-muted focus-visible:text-foreground focus-visible:outline-none",
              "focus-visible:ring-2 focus-visible:ring-ring",
            )}
          >
            <X className="h-3.5 w-3.5" />
          </button>
        </div>
        <div className="p-3">
          <LinkComponent {...ctaProps}>{ctaLabel}</LinkComponent>
        </div>
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef } from "react";

export interface UseLongPressPauseOptions {
  isOpen: boolean;
  /**
   * Hold duration in ms before pause kicks in. Default 200 — matches the
   * Instagram-feel mobile gesture. Tunable via
   * {@link StoryViewerProps.longPressThresholdMs}.
   */
  longPressThresholdMs?: number;
  onPause: () => void;
  onResume: () => void;
}

/**
 * v0.2.0 — additive long-press-to-pause gesture (Instagram-canonical mobile
 * pattern). Coexists with v0.1 middle-tap-pause (TapZones middle column) —
 * long-press is the primary mobile gesture; tap-to-pause stays as desktop
 * fallback (Q-V8 lock).
 *
 * Behavior: pointerdown starts a timer; if held past
 * `longPressThresholdMs`, `onPause()` fires + the press is marked active.
 * On pointerup (or pointercancel), if the press WAS active, `onResume()`
 * fires; if not yet active (released early), the timer is cleared without
 * pausing — so short taps continue to flow through TapZones normally.
 *
 * Wire onto the outer wrapping `<div>` of the viewer. Returns three handlers
 * to be spread as `onPointerDown` / `onPointerUp` / `onPointerCancel`. The
 * hook does NOT call `preventDefault` — TapZones' click handlers still fire
 * for short taps, preserving v0.1 single-tap-pause behavior.
 */
export function useLongPressPause(opts: UseLongPressPauseOptions) {
  const { isOpen, longPressThresholdMs = 200, onPause, onResume } = opts;
  const timerRef = useRef<number | null>(null);
  const isPressingRef = useRef(false);

  // Refs-mirror so the handlers are stable identity across renders.
  const onPauseRef = useRef(onPause);
  const onResumeRef = useRef(onResume);
  useEffect(() => {
    onPauseRef.current = onPause;
    onResumeRef.current = onResume;
  });

  // 0.6.2 - while a press is in flight, a release / cancel / blur ANYWHERE ends it, so a hold
  // released outside the card (or lost to an alt-tab) can never leave the story paused.
  const detachRef = useRef<(() => void) | null>(null);
  const endPressRef = useRef<() => boolean>(() => false);

  /**
   * Ends the press. Returns `true` when the release ended an ACTIVE long
   * press (the pause had fired) — the caller swallows the click that the
   * browser fires after that pointerup, so releasing never also taps a zone.
   */
  const handlePointerUp = useCallback((): boolean => {
    detachRef.current?.();
    detachRef.current = null;
    if (timerRef.current != null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    if (isPressingRef.current) {
      isPressingRef.current = false;
      onResumeRef.current();
      return true;
    }
    return false;
  }, []);

  useEffect(() => {
    endPressRef.current = handlePointerUp;
  }, [handlePointerUp]);

  const handlePointerDown = useCallback(() => {
    if (!isOpen) return;
    if (timerRef.current != null) return;
    timerRef.current = window.setTimeout(() => {
      isPressingRef.current = true;
      onPauseRef.current();
    }, longPressThresholdMs);
    const end = () => {
      endPressRef.current();
    };
    window.addEventListener("pointerup", end);
    window.addEventListener("pointercancel", end);
    window.addEventListener("blur", end);
    detachRef.current = () => {
      window.removeEventListener("pointerup", end);
      window.removeEventListener("pointercancel", end);
      window.removeEventListener("blur", end);
    };
  }, [isOpen, longPressThresholdMs]);

  // Cleanup on unmount.
  useEffect(
    () => () => {
      if (timerRef.current != null) clearTimeout(timerRef.current);
      detachRef.current?.();
      detachRef.current = null;
    },
    [],
  );

  return {
    handlePointerDown,
    handlePointerUp,
    handlePointerCancel: handlePointerUp,
  };
}

